Object.assign(window.TEM8_DICTIONARY, {"appreciated":{"oxford":{"phon":"əˈpriːʃieɪt","pos":"verb","senses":[{"en":"to recognize the good qualities of sb/sth","cn":"欣赏；赏识；重视"},{"en":"( not usually used in the progressive tenses","cn":"通常不用于进行时 ) to be grateful for sth that sb has done; to welcome sth 感激；感谢；欢迎"}]}},"appear":{"media":{"uk":"media/uk/appear__gb_1.mp3","us":"media/us/appear__us_1.mp3"},"oxford":{"phon":"əˈpɪə(r)","pos":"verb","senses":[{"en":"to start to be seen","cn":"出现；呈现；显现","g":"[intransitive]","sc":"be seen","ex":{"en":"Three days later a rash appeared.","cn":"三天后出现了皮疹。"}},{"en":"to begin to exist or be known or used for the first time","cn":"起源；出现；首次使用","g":"[intransitive]","sc":"begin to exist","ex":{"en":"Scientists are unsure when the virus first appeared.","cn":"科学家不确定病毒首次出现的时间。"}},{"en":"to give the impression of being or doing something","cn":"显得；看来；似乎","sc":"look/seem","ex":{"en":"She didn't appear at all surprised at the news.","cn":"她听到这消息时一点也没有显得吃惊。"}},{"en":"to be published or broadcast","cn":"出版；广播","g":"[intransitive]","sc":"of book, article, programme, etc.","ex":{"en":"His new book will be appearing in the spring.","cn":"他的新书将于春季出版。"}},{"en":"to take part in a film, play, television programme, etc.","cn":"演出","g":"[intransitive]","sc":"in film/play","ex":{"en":"He has appeared in over 60 movies.","cn":"他参演了 60 多部电影。"}},{"en":"to arrive at a place","cn":"抵达；来到","g":"[intransitive]","sc":"arrive","ex":{"en":"By ten o'clock Lee still hadn't appeared.","cn":"到十点钟李仍然没有露面。"}},{"en":"to be written or mentioned somewhere","cn":"记载；提及","g":"[intransitive]","sc":"be written/mentioned","ex":{"en":"Your name will appear at the front of the book.","cn":"你的名字将出现在书的封面上。"}},{"en":"to be present in court in order to give evidence or answer a charge","cn":"出庭（作证或答辩）；应诉","g":"[intransitive]","sc":"in court","ex":{"en":"A man will appear in court today charged with the murder.","cn":"一个被控犯谋杀罪的男人今天将出庭受审。"}},{"en":"to act as somebody’s lawyer in court","cn":"（作为律师）出庭；出庭当…的律师","g":"[intransitive]","sc":"in court","ex":{"en":"James Gilbert is the lawyer appearing for the defendant.","cn":"詹姆斯·吉尔伯特作为被告的辩护律师出庭。"}}]},"collins":{"senses":[{"pos":"V-LINK 连系动词","cn":"好像;似乎;看来","en":"If you say that something appears to be the way you describe it, you are reporting what you believe or what you have been told, though you cannot be sure it is true.","ex":{"en":"There appears to be increasing support for the leadership to take a more aggressive stance","cn":"好像有越来越多的人支持领导层采取更为强势的立场。"}},{"pos":"V-LINK 连系动词","cn":"看起来；显得","en":"If someone or something appears to have a particular quality or characteristic, they give the impression of having that quality or characteristic.","ex":{"en":"She did her best to appear more self-assured than she felt","cn":"她竭力让自己表现得比实际更自信。"}},{"pos":"VERB 动词","cn":"出现；显现","en":"When someone or something appears, they move into a position where you can see them.","ex":{"en":"A woman appeared at the far end of the street","cn":"一个女人远远出现在街的尽头。"}},{"pos":"VERB 动词","cn":"开始存在；产生","en":"When something new appears, it begins to exist or reaches a stage of development where its existence can be noticed.","ex":{"en":"...small white flowers which appear in early summer","cn":"初夏时绽放的白色小花"}},{"pos":"VERB 动词","cn":"（书籍等）出版，发表，问世","en":"When something such as a book appears, it is published or becomes available for people to buy.","ex":{"en":"I could hardly wait for 'Boys' World' to appear each month.","cn":"每个月我都翘首期盼着《男孩世界》的出版。"}},{"pos":"VERB 动词","cn":"演出；出场；表演","en":"When someone appears in something such as a play, a show, or a television programme, they take part in it.","ex":{"en":"Jill Bennett became John Osborne's fourth wife, and appeared in several of his plays","cn":"吉尔·本内特成为了约翰·奥斯本的第四任妻子，并参演过他的几部戏剧。"}},{"pos":"VERB 动词","cn":"出庭；到案","en":"When someone appears before a court of law or before an official committee, they go there in order to answer charges or to give information as a witness.","ex":{"en":"Two other executives appeared at Worthing Magistrates' Court charged with tax fraud","cn":"又有两个经理因偷税漏税指控被传唤到沃辛治安法庭。"}}]},"examples":[{"en":"Next month he will be appearing as Obama in a new play on Broadway.","cn":"下月他将在百老汇上演的一出新戏中扮演奥巴马。"},{"en":"It was too late to prevent the story from appearing in the national newspapers.","cn":"要阻止全国性报纸刊登这件事情已为时太晚。"}]},"appearance":{"media":{"uk":"media/uk/appearance__gb_1.mp3","us":"media/us/appearance__us_1.mp3"},"oxford":{"phon":"əˈpɪərəns","pos":"noun","senses":[{"en":"the way that somebody/something looks on the outside; what somebody/something seems to be","cn":"外貌；外观；外表","g":"[countable, uncountable]","sc":"way something looks/seems","ex":{"en":"the physical/outward/external appearance of something","cn":"某物的外观"}},{"en":"the fact of somebody/something arriving, especially when it is not expected","cn":"（尤指突然的）抵达，到来","g":"[countable, usually singular]","sc":"somebody/something arriving","ex":{"en":"The sudden appearance of a security guard caused them to drop the money and run.","cn":"保安人员突然出现，他们丢下钱就跑了。"}},{"en":"the moment at which something begins to exist or starts to be seen or used","cn":"起源；出现；首次使用","g":"[countable, usually singular]","sc":"somebody/something arriving","ex":{"en":"the early appearance of daffodils in spring","cn":"春来早开的水仙"}},{"en":"an act of appearing in public, especially as a performer, politician, etc., or in court","cn":"公开露面；演出；出庭","g":"[countable]","sc":"in public","ex":{"en":"The Dutch player will make his first appearance for Liverpool this Saturday.","cn":"这名荷兰球员将于本周六首次代表利物浦队亮相。"}},{"en":"an act of being published or broadcast","cn":"出版；广播","g":"[countable, usually singular]","sc":"being published/broadcast","ex":{"en":"the appearance of claims about the minister’s private life in the press","cn":"关于这位大臣私生活的说法见诸报端"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"出席；参加；露面","en":"When someone makes an appearance at a public event or in a broadcast, they take part in it.","ex":{"en":"It was the president's second public appearance to date","cn":"这是总统到那时为止的第二次公开露面。"}},{"pos":"N-SING 单数名词","cn":"外貌；外表；外观","en":"Someone's or something's appearance is the way that they look.","ex":{"en":"She used to be so fussy about her appearance","cn":"她过去非常在意自己的容貌。"}},{"pos":"N-SING 单数名词","cn":"（尤指出乎意料的）到来，出现","en":"The appearance of someone or something in a place is their arrival there, especially when it is unexpected.","ex":{"en":"The sudden appearance of a few bags of rice could start a riot.","cn":"突然出现几袋大米可能会引起骚乱。"}},{"pos":"N-SING 单数名词","cn":"出现;开始使用;问世","en":"The appearance of something new is its coming into existence or use.","ex":{"en":"Flowering plants were making their first appearance, but were still a rarity","cn":"显花植物开始出现了，但仍然很少。"}},{"pos":"N-SING 单数名词","cn":"样子;表现","en":"If something has the appearance of a quality, it seems to have that quality.","ex":{"en":"We tried to meet both children's needs without the appearance of favoritism or unfairness","cn":"我们尽力对两个孩子的需要都予以满足，而不显得有所偏向或袒护。"}},{"pos":"PHRASE 短语","cn":"从外表看来;显然","en":"If something is true to all appearances ,from all appearances, or by all appearances, it seems from what you observe or know about it that it is true.","ex":{"en":"He was a small and to all appearances an unassuming man.","cn":"他个子小，看上去不事张扬。"}},{"pos":"PHRASE 短语","cn":"装样子；撑场面；打肿脸充胖子","en":"If you keep up appearances, you try to behave and dress in a way that people expect of you, even if you can no longer afford it.","ex":{"en":"His parents' obsession with keeping up appearances haunted his childhood.","cn":"父母过于爱面子的做法在他儿时一直困扰着他。"}},{"pos":"PHRASE 短语","cn":"露一下面;到场稍作停留","en":"If you put in an appearance at an event, you go to it for a short time although you may not really want to, but do not stay.","ex":{"en":"You must put in an appearance, at least, or she'll think you're avoiding her.","cn":"至少，你必须露一下面，否则她会认为你在躲避她。"}}]},"examples":[{"en":"I don't want to go to the party, but I suppose I'd better put in an appearance (= go there for a short time).","cn":"我不想去参加这个聚会，不过我认为最好还是去露个面。"},{"en":"The Dutch player will make his first appearance for Liverpool this Saturday.","cn":"这名荷兰球员将于本星期六在利物浦队中首次亮相。"}]},"approach":{"media":{"uk":"media/uk/approach__gb_1.mp3","us":"media/us/approach__us_1.mp3"},"oxford":{"phon":"əˈprəʊtʃ","pos":"noun","senses":[{"en":"a way of dealing with somebody/something; a way of doing or thinking about something such as a problem or a task","cn":"（待人接物或思考问题的）方式，方法，态度","g":"[countable]","sc":"to problem/task","ex":{"en":"She took the wrong approach in her dealings with them.","cn":"她和他们打交道的方式错了。"}},{"en":"movement nearer to somebody/something in distance or time","cn":"（在距离或时间上的）靠近，接近","g":"[singular]","sc":"movement nearer","ex":{"en":"She hadn't heard his approach and jumped as the door opened.","cn":"她没有听见他走近的声音，所以门开时吓了一跳。"}},{"en":"the act of speaking to somebody about something, especially when making an offer or a request","cn":"接洽；建议；要求","g":"[countable]","sc":"offer/request","ex":{"en":"The club has made an approach to a local company for sponsorship.","cn":"俱乐部已向当地一家公司寻求赞助。"}},{"en":"attempts to start a personal or sexual relationship with somebody","cn":"试图与某人开始个人或性关系","g":"[plural]","lab":"old-fashioned","sc":"offer/request","ex":{"en":"She resented his persistent approaches.","cn":"她对他没完没了的纠缠极为反感。"}},{"en":"a path, road, etc. that leads to a place","cn":"通路；路径；道路","g":"[countable]","sc":"path/road","ex":{"en":"All the approaches to the palace were guarded by troops.","cn":"通往宫殿的所有道路都有军队守卫。"}},{"en":"the part of an aircraft’s flight immediately before landing","cn":"进场；进场着陆","g":"[countable]","sc":"of aircraft","ex":{"en":"to begin the final approach to the runway","cn":"开始进入跑道着陆"}},{"en":"a thing that is like something else that is mentioned","cn":"相似（或近似）的事物","g":"[singular]","sc":"something similar","ex":{"en":"That's the nearest approach to an apology you'll get from him.","cn":"那是他所能作出的最似歉意的表示。"}},{"en":"to come near to somebody/something in distance or time","cn":"（在距离或时间上）靠近，接近","g":"[intransitive, transitive]","sc":"move near","ex":{"en":"We could hear the train approaching.","cn":"我们能够听到火车开过来了。"},"pos":"verb"},{"en":"to speak to somebody about something, especially to ask them for something or to offer to do something","cn":"接洽；建议；要求","g":"[transitive]","sc":"offer/ask","ex":{"en":"We have been approached by a number of companies that are interested in our product.","cn":"一些对我们的产品感兴趣的公司已和我们接洽。"},"pos":"verb"},{"en":"to come close to something in amount, level or quality","cn":"（在数额、水平或质量上）接近","g":"[transitive]","sc":"amount/quality","ex":{"en":"Interest rates are approaching zero.","cn":"利率正在逼近零。"},"pos":"verb"},{"en":"to start dealing with a problem, task, etc. in a particular way","cn":"着手处理；对付","g":"[transitive]","sc":"problem/task","ex":{"en":"to approach a subject/matter/task/question","cn":"处理题材／事项／任务／问题"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"靠近;接近;走近","en":"When you approach something, you get closer to it.","ex":{"en":"He didn't approach the front door at once","cn":"他没有马上走向前门。"}},{"pos":"N-COUNT 可数名词","cn":"路径;途径;道路","en":"An approach to a place is a road, path, or other route that leads to it.","ex":{"en":"The path serves as an approach to the boat house.","cn":"这条小路通往船屋。"}},{"pos":"VERB 动词","cn":"与…接洽；找…商量","en":"If you approach someone about something, you speak to them about it for the first time, often making an offer or request.","ex":{"en":"When Chappel approached me about the job, my first reaction was of disbelief","cn":"当查普尔为这份工作找我商量时，我的第一反应是不相信。"}},{"pos":"VERB 动词","cn":"探讨；处理；对待","en":"When you approach a task, problem, or situation in a particular way, you deal with it or think about it in that way.","ex":{"en":"The Bank has approached the issue in a practical way","cn":"银行已经实际解决了这个问题。"}},{"pos":"N-COUNT 可数名词","cn":"方法;态度;手段","en":"Your approach to a task, problem, or situation is the way you deal with it or think about it.","ex":{"en":"We will be exploring different approaches to gathering information.","cn":"我们将探索收集信息的不同方法。"}},{"pos":"VERB 动词","cn":"临近；来临","en":"As a future time or event approaches, it gradually gets nearer as time passes.","ex":{"en":"As autumn approached, the plants and colours in the garden changed.","cn":"秋天临近，花园中的草木和颜色也发生了变化。"}},{"pos":"VERB 动词","cn":"接近（未来时间或事件）","en":"As you approach a future time or event, time passes so that you get gradually nearer to it.","ex":{"en":"We approach the end of the year with the economy slowing and little sign of cheer.","cn":"接近年末时，我们面临经济迟滞、处处萧条的局面。"}},{"pos":"VERB 动词","cn":"近似；接近于","en":"If something approaches a particular level or state, it almost reaches that level or state.","ex":{"en":"Oil prices have approached their highest level for almost ten years","cn":"石油价格已接近近10年中的最高水平。"}}]},"examples":[{"en":"She hadn't heard his approach and jumped as the door opened.","cn":"她没有听见他走近的声音，所以门开时吓了一跳。"},{"en":"We have been approached by a number of companies that are interested in our product.","cn":"一些对我们的产品感兴趣的公司已和我们接洽。"}]},"apes":{"oxford":{"phon":"eɪp","pos":"noun","senses":[{"en":"a large animal like a monkey , with no tail. There are different types of ape.","cn":"类人猿；无尾猿"},{"en":"( slang ) ( especially NAmE ) to become extremely angry or excited","cn":"暴跳如雷；激动异常"}]},"media":{"uk":"media/uk/ape__gb_1.mp3","us":"media/us/ape__us_1.mp3"}},"aptitude":{"media":{"uk":"media/uk/aptitude__gb_1.mp3","us":"media/us/aptitude__us_1.mp3"},"oxford":{"phon":"ˈæptɪtjuːd","pos":"noun","senses":[{"en":"natural ability or skill at doing something","cn":"天资；天生的才能；天赋","ex":{"en":"an aptitude test (= one designed to show whether somebody has the natural ability for a particular job or course of education)","cn":"能力倾向测验"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"天资;天赋;才能","en":"Someone's aptitude for a particular kind of work or activity is their ability to learn it quickly and to do it well.","ex":{"en":"An aptitude for computing is beneficial for students taking this degree.","cn":"计算才能对于攻读这个学位的学生有益处。"}}]},"examples":[{"en":"His aptitude for dealing with children got him the job.","cn":"他善于和儿童打交道的本事使他得到了这份工作。"},{"en":"She showed a natural aptitude for the work.","cn":"她表现出了做这工作的天赋。"}]},"approving":{"oxford":{"phon":"əˈpruːvɪŋ","pos":"adjective","senses":[{"en":"showing that you believe that somebody/something is good or acceptable","cn":"赞成的；同意的","ex":{"en":"He gave me an approving nod.","cn":"他向我点头表示同意。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（反应、话语等）表示赞许的，表示嘉许的","en":"An approving reaction or remark shows support for something, or satisfaction with it.","ex":{"en":"His mother leaned forward and gave him an approving look.","cn":"他的母亲探身向前，对他投以赞许的目光。"}}]},"media":{"uk":"media/uk/approving__gb_1.mp3","us":"media/us/approving__us_1.mp3"},"examples":[{"en":"She looked at him approvingly and smiled.","cn":"她面带微笑赞许地望着他。"},{"en":"He gave me an approving nod.","cn":"他向我点头表示同意。"}]},"approval":{"media":{"uk":"media/uk/approval__gb_1.mp3","us":"media/us/approval__us_1.mp3"},"oxford":{"phon":"əˈpruːvl","pos":"noun","senses":[{"en":"the feeling that somebody/something is good or acceptable; a positive opinion of somebody/something","cn":"赞成；同意","g":"[uncountable]","ex":{"en":"She desperately wanted to win her father's approval.","cn":"她急不可待地想赢得她父亲的赞同。"}},{"en":"agreement to, or permission for something, especially a plan or request","cn":"批准，通过，认可（计划、要求等）","g":"[uncountable, countable]","ex":{"en":"The plan will be submitted to the committee for official approval.","cn":"该计划将送交委员会正式批准。"}},{"en":"if you buy goods or if goods are sold on approval, you can use them for a time without paying, until you decide if you want to buy them or not","cn":"（商品）试用，包退包换","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"赞成；同意","en":"If you win someone's approval for something that you ask for or suggest, they agree to it.","ex":{"en":"...efforts to win congressional approval for an aid package for Moscow","cn":"为获得国会准许向莫斯科提供一揽子援助而付出的努力"}},{"pos":"N-VAR 可变名词","cn":"认可;通过","en":"Approval is a formal or official statement that something is acceptable.","ex":{"en":"The testing and approval of new drugs will be speeded up.","cn":"新药品的检测和审批速度将会加快。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赞许;嘉许","en":"If someone or something has your approval, you like and admire them.","ex":{"en":"His son had an obsessive drive to gain his father's approval","cn":"他儿子非常渴望得到父亲的嘉许。"}},{"pos":"PHRASE 短语","cn":"（正式）认可;批准;核准","en":"If a person or organization gives something their seal of approval or their stamp of approval, they officially say that they like it or think it is acceptable.","ex":{"en":"Ministers have put their seal of approval on the proposal","cn":"部长们已经批准了该提案。"}}]},"examples":[{"en":"They required/received approval for the proposal from the shareholders.","cn":"他们要求/获得股东对这项提议的批准。"},{"en":"Senior management have given their seal of approval (= formal approval) to the plans.","cn":"高层管理部门已经正式批准这些计划。"}]},"apprentice":{"oxford":{"phon":"əˈprentɪs","pos":"noun","senses":[{"en":"a young person who works for an employer for a fixed period of time in order to learn the particular skills needed in their job","cn":"学徒；徒弟","ex":{"en":"an apprentice electrician/chef","cn":"电工／厨师学徒"}},{"en":"to make somebody an apprentice","cn":"使某人当（某人的）学徒","ex":{"en":"He was apprenticed to his uncle as a carpenter.","cn":"他给叔叔当木匠学徒。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"学徒；徒弟","en":"An apprentice is a young person who works for someone in order to learn their skill.","ex":{"en":"I started off as an apprentice and worked my way up","cn":"我从学徒开始干起，逐步上升。"}},{"pos":"VERB 动词","cn":"使拜师于；使当…的学徒","en":"If a young person is apprenticed to someone, they go to work for them in order to learn their skill.","ex":{"en":"I was apprenticed to a builder when I was fourteen.","cn":"14岁时，我拜一个建筑工人为师当学徒。"}}]},"media":{"uk":"media/uk/apprentice__gb_1.mp3","us":"media/us/apprentice__us_1.mp3"},"examples":[{"en":"an apprentice electrician/chef","cn":"电工/厨师学徒"},{"en":"She works in the hairdresser’s as an apprentice.","cn":"她在美发店当学徒。"}]},"apart":{"media":{"uk":"media/uk/apart__gb_1.mp3","us":"media/us/apart__us_1.mp3"},"oxford":{"phon":"əˈpɑːt","pos":"adverb","senses":[{"en":"separated by a distance, of space or time","cn":"（指空间或时间）相隔，相距","lab":"figurative","ex":{"en":"The two houses stood 500 metres apart.","cn":"两座房子相距 500 米。"}},{"en":"not together; separate or separately","cn":"不在一起；分离；分开","ex":{"en":"We're living apart now.","cn":"我们现在不住在一起。"}},{"en":"into pieces","cn":"成碎片","ex":{"en":"The whole thing just came apart in my hands.","cn":"这整件东西偏偏在我手里破裂了。"}},{"en":"used to say that somebody/something is not included in what you are talking about","cn":"（指所说的不包括在内）除外","ex":{"en":"Victoria apart, not one of them seems suitable for the job.","cn":"除了维多利亚，看来他们谁也不适合这个工作。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（在空间上）相隔，相距","en":"When people or things are apart, they are some distance from each other.","ex":{"en":"He was standing a bit apart from the rest of us, watching us","cn":"他站在离我们其余人不远的地方，看着我们。"}},{"pos":"ADV 副词","cn":"往不同方向；分开","en":"If two people or things move apart or are pulled apart, they move away from each other.","ex":{"en":"John and Isabelle moved apart, back into the sun","cn":"约翰和伊莎贝拉彼此分开，回到了阳光下。"}},{"pos":"ADV 副词","cn":"分手；分离","en":"If two people are apart, they are no longer living together or spending time together, either permanently or just for a short time.","ex":{"en":"It was the first time Jane and I had been apart for more than a few days","cn":"那是我第一次和简分开数日。"}},{"pos":"ADV 副词","cn":"成零碎;散开","en":"If you take something apart, you separate it into the pieces that it is made of. If it comes or falls apart, its parts separate from each other.","ex":{"en":"When the clock stopped he took it apart to find out what was wrong","cn":"钟一不走了，他就把它拆开看看哪儿出毛病了。"}},{"pos":"ADV 副词","cn":"垮掉；分裂；解体","en":"If something such as an organization or relationship falls apart, or if something tears it apart, it can no longer continue because it has serious difficulties.","ex":{"en":"Any manager knows that his company will start falling apart if his attention wanders","cn":"每个经理都知道只要自己的注意力有所分散，公司就会分崩离析。"}},{"pos":"ADV 副词","cn":"与众不同地；独特地","en":"If something sets someone or something apart, it makes them different from other people or things.","ex":{"en":"What really sets Mr Thaksin apart is that he comes from northern Thailand","cn":"他信先生真正与众不同之处是他来自泰国北部。"}},{"pos":"ADJ 形容词","cn":"意见不一致的；有分歧的","en":"If people or groups are a long way apart on a particular topic or issue, they have completely different views and disagree about it.","ex":{"en":"Officials say they're so far apart on such a wide range of issues there's no telling how long the talks could drag on","cn":"官员们声称他们在许多问题上分歧甚大，所以无法预见谈判将拖多久。"}},{"pos":"PHRASE 短语","cn":"区分;分辨","en":"If you can't tell two people or things apart, they look exactly the same to you.","ex":{"en":"I can still only tell Mark and Dave apart by the colour of their shoes!","cn":"我仍然只能根据鞋子的颜色来区分马克和戴夫！"}},{"pos":"ADV 副词","cn":"除了…外（别无）","en":"You use apart from when you are making an exception to a general statement.","ex":{"en":"The room was empty apart from one man seated beside the fire","cn":"除了有个男人坐在火炉边，房间里空荡荡的。"}},{"pos":"PREP-PHRASE 短语介词","cn":"除…之外（表示例外）","en":"You use apart when you are making an exception to a general statement.","ex":{"en":"This was, New York apart, the first American city I had ever been in where people actually lived downtown.","cn":"除了纽约，这是我到过的第一个人们确实住在市中心的美国城市。"}},{"pos":"PREP-PHRASE 短语介词","cn":"除…外（尚有）；此外","en":"You use apart from to indicate that you are aware of one aspect of a situation, but that you are going to focus on another aspect.","ex":{"en":"Illiteracy threatens Britain's industrial performance. But, quite apart from that, the individual who can't read or write is unlikely to get a job","cn":"文盲的存在影响着英国的产业效益。但是，除此以外，更重要的是那些不具备读写能力的人也不太可能找到工作。"}},{"pos":"ADV 副词","cn":"除…以外（尚有）;此外","en":"You use apart to indicate that you are aware of one aspect of a situation, but that you are going to focus on another aspect.","ex":{"en":"That argument apart, it is for the Germans themselves to work out how their forces should come together.","cn":"撇开那场纷争不谈，德国人自己也应该考虑一下如何将各种力量拧成一股绳。"}}]},"examples":[{"en":"Victoria apart, not one of them seems suitable for the job.","cn":"除了维多利亚，看来他们谁也不适合这个工作。"},{"en":"I can't tell the twins apart (= see the difference between them).","cn":"我分不出这一对双胞胎中谁是谁。"}]},"appeal":{"media":{"uk":"media/uk/appeal__gb_1.mp3","us":"media/us/appeal__us_1.mp3"},"oxford":{"phon":"əˈpiːl","pos":"noun","senses":[{"en":"a deeply felt request for money, help or information that is needed immediately, especially one made by a charity or by the police","cn":"（尤指慈善机构或警方的）呼吁，吁请，恳求","g":"[countable, uncountable]","ex":{"en":"to launch a TV appeal for donations to the charity","cn":"通过电视呼吁为该慈善组织捐赠"}},{"en":"a quality that makes somebody/something attractive or interesting","cn":"吸引力；感染力；魅力","g":"[uncountable]","ex":{"en":"mass/wide/popular/broad/universal appeal","cn":"广泛的吸引力；普遍的吸引力"}},{"en":"a formal request to a court or to somebody in authority for a judgement or a decision to be changed","cn":"上诉；申诉","g":"[countable, uncountable]","lab":"British English","ex":{"en":"to lodge an appeal","cn":"提出上诉"}},{"en":"an indirect suggestion that any good, fair or reasonable person would act in a particular way","cn":"启发；打动","g":"[countable]","ex":{"en":"I relied on an appeal to his finer feelings.","cn":"我寄望能唤起他的爱心。"}},{"en":"to make a deeply felt request, especially for something that is needed immediately","cn":"呼吁；恳求","g":"[intransitive]","ex":{"en":"I am appealing (= asking for money) on behalf of the famine victims.","cn":"我代表饥民吁请捐款。"},"pos":"verb"},{"en":"to attract or interest somebody","cn":"有吸引力；有感染力；引起兴趣","g":"[intransitive]","ex":{"en":"The prospect of a long wait in the rain did not appeal.","cn":"想到要在雨中久等使人扫兴。"},"pos":"verb"},{"en":"to make a formal request to a court or to somebody in authority for a judgment or a decision to be changed","cn":"上诉；申诉","g":"[intransitive]","ex":{"en":"He said he would appeal after being found guilty on four counts of murder.","cn":"法庭判决他犯有四项谋杀罪，他表示要上诉。"},"pos":"verb"},{"en":"to try to persuade somebody to do something by suggesting that it is a fair, reasonable or honest thing to do","cn":"启发；劝说；打动","g":"[intransitive]","ex":{"en":"They needed to appeal to his sense of justice.","cn":"他们需要激发他的正义感。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"呼吁;恳请;恳求","en":"If you appeal to someone to do something, you make a serious and urgent request to them.","ex":{"en":"The Prime Minister appealed to young people to use their vote","cn":"首相呼吁年轻人行使他们的投票权。"}},{"pos":"N-COUNT 可数名词","cn":"呼吁;恳请;恳求","en":"An appeal is a serious and urgent request.","ex":{"en":"He has a message from King Fahd, believed to be an appeal for Arab unity","cn":"法赫德国王传话给他，据信内容是呼吁整个阿拉伯世界团结起来。"}},{"pos":"N-COUNT 可数名词","cn":"（为慈善或正义事业的）募捐","en":"An appeal is an attempt to raise money for a charity or for a good cause.","ex":{"en":"...an appeal to save a library containing priceless manuscripts","cn":"为挽救存有珍贵手稿的图书馆的一次募捐"}},{"pos":"VERB 动词","cn":"上诉;申诉","en":"If you appeal to someone in authority against a decision, you formally ask them to change it. In British English, you appeal against something. In American English, you appeal something.","ex":{"en":"He said they would appeal against the decision","cn":"他说他们将对该决议提出申诉。"}},{"pos":"N-VAR 可变名词","cn":"上诉;申诉","en":"An appeal is a formal request for a decision to be changed.","ex":{"en":"Heath's appeal against the sentence was later successful","cn":"希思对判决不服提出上诉，后来胜诉了。"}},{"pos":"VERB 动词","cn":"对…有吸引力；使感兴趣","en":"If something appeals to you, you find it attractive or interesting.","ex":{"en":"On the other hand, the idea appealed to him","cn":"从另一方面来说，这个想法又使他很感兴趣。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"吸引力;感染力","en":"The appeal of something is a quality that it has which people find attractive or interesting.","ex":{"en":"Its new title was meant to give the party greater public appeal","cn":"新的党名意在使该党对公众具有更强的吸引力。"}}]},"examples":[{"en":"He said he would appeal after being found guilty on four counts of murder.","cn":"法庭判决他犯有四项谋杀罪，他表示要上诉。"},{"en":"The child's mother made an emotional appeal on TV for his return.","cn":"孩子的母亲在电视上恳切地要求儿子回家。"}]},"applying":{"oxford":{"phon":"əˈplaɪ","pos":"verb","senses":[{"en":"to make a formal request, usually in writing, for sth such as a job, a place at college, university, etc. （","cn":"通常以书面形式）申请，请求"},{"en":"to use sth or make sth work in a particular situation","cn":"使用；应用"}]},"media":{"uk":"media/uk/apply__gb_1.mp3","us":"media/us/apply__us_1.mp3"}},"approved":{"oxford":{"phon":"əˈpruːv","pos":"verb","senses":[{"en":"to think that sb/sth is good, acceptable or suitable","cn":"赞成；同意"},{"en":"to officially agree to a plan, request, etc.","cn":"批准，通过（计划、要求等）"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（方法或行为）被正式接受的，被正式认可的","en":"An approved method or course of action is officially accepted as appropriate in a particular situation.","ex":{"en":"The approved method of cleaning is industrial sand-blasting.","cn":"得到正式认可的清洁方法是工业喷砂清洗。"}}]},"media":{"uk":"media/ldoce/hwd/bre/f/ld41approved.mp3","us":"media/ldoce/hwd/ame/f/ld41approved.mp3"},"examples":[{"en":"Funding is available for approved courses.","cn":"已经核准的课程可获得拨款。"}]},"ape":{"media":{"uk":"media/uk/ape__gb_1.mp3","us":"media/us/ape__us_1.mp3"},"oxford":{"phon":"eɪp","pos":"noun","senses":[{"en":"a large animal like a monkey, with no tail. There are different types of ape.","cn":"类人猿","ex":{"en":"the great apes (= for example, orangutans or chimpanzees)","cn":"类人猿（如猩猩、黑猩猩）"}},{"en":"to do something in the same way as somebody else, especially when it is not done very well","cn":"（尤指笨拙地）模仿，学…的样子","lab":"British English, disapproving，，","ex":{"en":"For years the British film industry merely aped Hollywood.","cn":"多年来，英国电影业一味模仿好莱坞。"},"pos":"verb"},{"en":"to copy the way somebody else behaves or talks, in order to make fun of them","cn":"（为了取笑）学…的样，模仿","lab":"especially North American English","ex":{"en":"We used to ape the teacher's southern accent.","cn":"我们过去常模仿老师的南方口音。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"无尾猿；类人猿；猿","en":"Apes are chimpanzees, gorillas, and other animals in the same family.","ex":{"en":"...the theory that man is descended from the apes.","cn":"认为人类是从类人猿演变而来的理论"}},{"pos":"VERB 动词","cn":"模仿；学…的样子","en":"If you ape someone's speech or behaviour, you imitate it.","ex":{"en":"Modelling yourself on someone you admire is not the same as aping all they say or do.","cn":"以偶像为榜样并不是说要模仿他们的一言一行。"}},{"pos":"PHRASE 短语","cn":"怒不可遏;暴跳如雷","en":"If someone goes ape, they become very angry and upset.","ex":{"en":"When Colonel Harper found out, he would go ape.","cn":"哈珀上校发现了一定会勃然大怒。"}}]},"examples":[{"en":"For years the British film industry merely aped Hollywood.","cn":"多年来，英国电影业一味模仿好莱坞。"},{"en":"We used to ape the teacher's southern accent.","cn":"我们过去常模仿老师的南方口音。"}]},"approximately":{"oxford":{"phon":"əˈprɒksɪmətli","pos":"adverb","senses":[{"en":"used to show that something is almost, but not completely, accurate or correct","cn":"大概；大约；约莫","ex":{"en":"The journey took approximately seven hours.","cn":"旅程大约花了七个小时。"}}]},"media":{"uk":"media/uk/approximately__gb_1.mp3","us":"media/us/approximately__us_1.mp3"},"examples":[{"en":"The journey took approximately seven hours.","cn":"旅程大约花了七个小时。"},{"en":"The plane will be landing in approximately 20 minutes.","cn":"飞机大约在20分钟后着陆。"}]},"apparently":{"media":{"uk":"media/uk/apparently__gb_1.mp3","us":"media/us/apparently__us_1.mp3"},"oxford":{"phon":"əˈpærəntli","pos":"adverb","senses":[{"en":"according to what you have heard or read; according to the way something appears","cn":"可见；看来；显然","ex":{"en":"Apparently they are getting divorced soon.","cn":"看样子，他们很快就要离婚。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"据说；未必真实地","en":"You use apparently to indicate that the information you are giving is something that you have heard, but you are not certain that it is true.","ex":{"en":"Apparently the girls are not at all amused by the whole business","cn":"据说女孩们觉得整件事情一点也不好笑。"}},{"pos":"ADV 副词","cn":"好像;似乎;看来","en":"You use apparently to refer to something that seems to be true, although you are not sure whether it is or not.","ex":{"en":"The recent deterioration has been caused by an apparently endless recession","cn":"看似永无止境的经济衰退导致了最近的恶化。"}}]},"examples":[{"en":"I thought she had retired, but apparently she hasn't.","cn":"我原以为她退休了，但显然她还没有退。"},{"en":"He paused, apparently lost in thought.","cn":"他停顿下来，显然陷入了沉思。"}]},"applies":{"oxford":{"phon":"əˈplaɪ","pos":"verb","senses":[{"en":"to make a formal request, usually in writing, for sth such as a job, a place at college, university, etc. （","cn":"通常以书面形式）申请，请求"},{"en":"to use sth or make sth work in a particular situation","cn":"使用；应用"}]},"media":{"uk":"media/uk/apply__gb_1.mp3","us":"media/us/apply__us_1.mp3"}},"apprehensively":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not feeling happy or relaxed because you keep thinking about a problem or something bad that might happen","cn":""},{"en":"worried because you think something bad might happen or has happened. Anxious is more formal than worried , and is often used about a general feeling of worry, when you are not sure what has happened","cn":""}]},"examples":[{"en":"We’d been a little apprehensive about their visit.","cn":"","src":"ld"},{"en":"I was apprehensive that something would go wrong.","cn":"","src":"ld"}],"media":{"uk":"media/uk/apprehensively__gb_1.mp3","us":"media/us/apprehensively__us_1.mp3"},"oxford":{"phon":"ˌæprɪˈhensɪvli","pos":"adverb","senses":[{"en":"in a worried or frightened way because you think something unpleasant may happen","cn":"忧虑的；担心的；疑惧的；恐惧的"}]}},"appropriate":{"media":{"uk":"media/uk/appropriate__gb_1.mp3","us":"media/us/appropriate__us_1.mp3"},"oxford":{"phon":"əˈprəʊpriət","pos":"adjective","senses":[{"en":"suitable, acceptable or correct for the particular circumstances","cn":"合适的；恰当的","ex":{"en":"an appropriate response/measure/method","cn":"恰如其分的反应；恰当的措施／方法"}},{"en":"to take something, somebody’s ideas, etc. for your own use, especially illegally or without permission","cn":"盗用；挪用；占用；侵吞","ex":{"en":"He was accused of appropriating club funds.","cn":"他被控盗用俱乐部资金。"},"pos":"verb"},{"en":"to take or give something, especially money for a particular purpose","cn":"拨（专款等）","ex":{"en":"Five million dollars have been appropriated for research into the disease.","cn":"已拨款五百万美元用于这种疾病的研究。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"适当的;合适的;恰当的","en":"Something that is appropriate is suitable or acceptable for a particular situation.","ex":{"en":"It is appropriate that Irish names dominate the list","cn":"名单上大部分是爱尔兰名字，这没什么不合适的。"}},{"pos":"VERB 动词","cn":"私占；侵吞；盗用；挪用","en":"If someone appropriates something which does not belong to them, they take it, usually without the right to do so.","ex":{"en":"Several other newspapers have appropriated the idea","cn":"另外有几家报社已盗用了这个创意。"}},{"pos":"VERB 动词","cn":"拨出（专款）","en":"If a government or organization appropriates an amount of money for a particular purpose, it reserves it for that purpose.","ex":{"en":"Senator Lugar is skeptical that Congress will appropriate more funding for this purpose.","cn":"参议员卢格怀疑国会是否会拨出更多资金用于此目的。"}}]},"examples":[{"en":"Please debit my Mastercard/Visa/American Express card ( delete as appropriate ) (= cross out the options that do not apply).","cn":"请在我的万事达/维萨/美国运通信用卡（删除不适用者）账户中扣除。"},{"en":"The government has been accused of not responding appropriately to the needs of the homeless.","cn":"政府未采取恰当的措施以应无家可归者的需要，为此已受到谴责。"}]},"appliance":{"media":{"img":["media/pic/appliances_comp.jpg","media/thumb/foodprocessor.jpg"],"uk":"media/uk/appliance__gb_1.mp3","us":"media/us/appliance__us_1.mp3"},"oxford":{"phon":"əˈplaɪəns","pos":"noun","senses":[{"en":"a machine that is designed to do a particular thing in the home, such as preparing food, heating or cleaning","cn":"（家用）电器，器具","ex":{"en":"electrical/household appliances","cn":"电器；家用器具"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（家用）电器，器械，装置","en":"An appliance is a device or machine in your home that you use to do a job such as cleaning or cooking. Appliances are often electrical.","ex":{"en":"He could also learn to use the vacuum cleaner, the washing machine and other household appliances.","cn":"他可以再学学使用吸尘器、洗衣机和其他家用电器。"}},{"pos":"N-SING 单数名词","cn":"（技术或知识的）使用，应用","en":"The appliance of a skill or of knowledge is its use for a particular purpose.","ex":{"en":"These advances were the result of the intellectual appliance of science.","cn":"这些进步是巧妙应用科学的结果。"}}]},"examples":[{"en":"They sell a wide range of domestic appliances — washing machines, dishwashers and so on.","cn":"他们出售各种家用电器，如洗衣机、洗碗机等等。"},{"en":"electrical/household appliances","cn":"电器；家用器具"}]},"approve":{"oxford":{"phon":"əˈpruːv","pos":"verb","senses":[{"en":"to think that somebody/something is good, acceptable or suitable","cn":"赞成；同意","g":"[intransitive]","lab":"formal","ex":{"en":"I told my mother I wanted to leave school but she didn't approve.","cn":"我告诉母亲我不想继续上学，但是母亲不同意。"}},{"en":"to officially agree to a plan, request, etc.","cn":"批准，通过（计划、要求等）","g":"[transitive]","ex":{"en":"The committee unanimously approved the plan.","cn":"委员会一致通过了计划。"}},{"en":"to say that something is good enough to be used or is correct","cn":"认可；核准","g":"[transitive, often passive]","ex":{"en":"The course is approved by the Department for Education.","cn":"课程已获教育部核准。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"赞成；同意","en":"If you approve of an action, event, or suggestion, you like it or are pleased about it.","ex":{"en":"Not everyone approves of the festival","cn":"不是所有人都赞成庆祝该节日。"}},{"pos":"VERB 动词","cn":"赞许;嘉许;喜欢","en":"If you approve of someone or something, you like and admire them.","ex":{"en":"You've never approved of Henry, have you?","cn":"你从来没有喜欢过亨利，对吗？"}},{"pos":"VERB 动词","cn":"批准；认可；通过","en":"If someone in a position of authority approves a plan or idea, they formally agree to it and say that it can happen.","ex":{"en":"The Russian Parliament has approved a program of radical economic reforms","cn":"俄罗斯议会已经通过一项重大经济改革方案。"}},{"pos":"VERB 动词","cn":"批准；核准","en":"If a product or person is approved by an official organization, they are declared to be of a good enough standard to be used or employed.","ex":{"en":"We have three suppliers in all who are approved by the Organic Farm Food Association.","cn":"我们总共有3家获有机农产品协会认可的供货商。"}}]},"media":{"uk":"media/uk/approve__gb_1.mp3","us":"media/us/approve__us_1.mp3"},"examples":[{"en":"I told my mother I wanted to leave school but she didn't approve.","cn":"我告诉母亲我不想继续上学，但是母亲不同意。"},{"en":"The committee unanimously approved the plan.","cn":"委员会一致通过了计划。"}]},"apt":{"media":{"uk":"media/uk/apt__gb_1.mp3","us":"media/us/apt__us_1.mp3"},"oxford":{"phon":"æpt","pos":"adjective","senses":[{"en":"suitable or appropriate in the circumstances","cn":"恰当的；适当的","ex":{"en":"a particularly apt description/name/comment","cn":"特别恰当的描述／名字／评论"}},{"en":"likely or tending naturally to do something","cn":"易于…；有…倾向","ex":{"en":"apt to be forgetful/careless","cn":"健忘；常常粗心大意"}},{"en":"a person who has a natural ability to learn and understand","cn":"天资聪颖的人"},{"en":"apartment","cn":"公寓","ex":{"en":"apt.18, 1627 Chestnut St.","cn":"栗树街 1627 号 18 号公寓"},"pos":"abbreviation"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（话语、描述或选择）合适的，恰当的，贴切的","en":"An apt remark, description, or choice is especially suitable.","ex":{"en":"The words of this report are as apt today as in 1929.","cn":"这份报告的措词用在今天和用在1929年一样贴切。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"易于…的；有…倾向的","en":"If someone is apt to do something, they often do it and so it is likely that they will do it again.","ex":{"en":"She was apt to raise her voice and wave her hands about","cn":"她动不动就拔高嗓门，并挥舞双手。"}}]},"examples":[{"en":"Babies are apt to put objects into their mouths.","cn":"婴儿爱把东西往嘴里塞。"},{"en":"a particularly apt description/name/comment","cn":"特别恰当的描述/名字/评论"}]},"appreciation":{"media":{"uk":"media/uk/appreciation__gb_1.mp3","us":"media/us/appreciation__us_1.mp3"},"oxford":{"phon":"əˌpriːʃiˈeɪʃn","pos":"noun","senses":[{"en":"pleasure that you have when you recognize and enjoy the good qualities of somebody/something","cn":"欣赏","g":"[uncountable]","ex":{"en":"She shows little appreciation of good music.","cn":"她感受不到美好音乐的妙处。"}},{"en":"a full understanding of something, such as a situation or a problem, and of what it involves","cn":"理解；体谅；同情","g":"[uncountable, singular]","ex":{"en":"I had no appreciation of the problems they faced.","cn":"我没有体谅到他们所面临的困难。"}},{"en":"the feeling of being grateful for something","cn":"感激；感谢","g":"[uncountable, singular]","ex":{"en":"I would like to express my appreciation and thanks to you all.","cn":"我想对你们所有人表达我的感激和谢意。"}},{"en":"increase in value over a period of time","cn":"增值；升值","g":"[uncountable, singular]","ex":{"en":"an appreciation in the value of the house","cn":"房屋升值"}},{"en":"a piece of writing or a speech in which the strengths and weaknesses of somebody/something, especially an artist or a work of art, are discussed and judged","cn":"（尤指艺术方面的）鉴定，评价，评估","g":"[countable]","lab":"formal","ex":{"en":"They were asked to write an appreciation of a poem of their choice.","cn":"他们被要求为自己选择的一首诗写一篇欣赏。"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"欣赏；鉴赏;赏识","en":"Appreciation of something is the recognition and enjoyment of its good qualities.","ex":{"en":"...an investigation into children's understanding and appreciation of art","cn":"就孩子对艺术的理解和欣赏所作的调查"}},{"pos":"N-SING 单数名词","cn":"感谢；感激","en":"Your appreciation for something that someone does for you is your gratitude for it.","ex":{"en":"He expressed his appreciation for what he called Saudi Arabia's moderate and realistic oil policies.","cn":"他表示很感激沙特阿拉伯推行的被他称作稳健而务实的石油政策。"}},{"pos":"N-SING 单数名词","cn":"领会；了解；认识","en":"An appreciation of a situation or problem is an understanding of what it involves.","ex":{"en":"They have a stronger appreciation of the importance of economic incentives.","cn":"他们对经济激励的重要性有了更深的理解。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"升值；增值","en":"Appreciation in the value of something is an increase in its value over a period of time.","ex":{"en":"You have to take capital appreciation of the property into account.","cn":"你必须将该处房产的资本增值考虑在内。"}},{"pos":"N-COUNT 可数名词","cn":"（对艺术家、表演者或其作品的）评论，评价","en":"An appreciation of an artist or performer or of their work is a speech or piece of writing in which they are discussed and assessed.","ex":{"en":"I had written an appreciation of Hernandez for a magazine.","cn":"我为一家杂志社写过一篇评论埃尔南德斯的文章。"}}]},"examples":[{"en":"Please accept this gift in appreciation of all you've done for us.","cn":"承蒙鼎力相助，不胜感激，谨备薄礼，敬请笑纳。"},{"en":"I had no appreciation of the problems they faced.","cn":"我没有体谅到他们所面临的困难。"}]},"applied":{"media":{"uk":"media/uk/applied__gb_1.mp3","us":"media/us/applied__us_1.mp3"},"oxford":{"phon":"əˈplaɪd","pos":"adjective","senses":[{"en":"used in a practical way; not theoretical","cn":"应用的；实用的","ex":{"en":"applied mathematics (= as used by engineers, etc.)","cn":"应用数学"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"应用的；实用的","en":"An applied subject of study has a practical use, rather than being concerned only with theory.","ex":{"en":"...Applied Physics.","cn":"应用物理学"}}]},"examples":[{"en":"applied mathematics (= as used by engineers, etc.)","cn":"应用数学"}]},"apple":{"media":{"img":["media/ldoce/img/apple.jpg","media/pic/fruit_comp.jpg"],"uk":"media/uk/apple__gb_1.mp3","us":"media/us/apple__us_1.mp3"},"oxford":{"phon":"ˈæpl","pos":"noun","senses":[{"en":"a round fruit with shiny red or green skin that is fairly hard and white inside","cn":"苹果","ex":{"en":"Peel and core the apples.","cn":"将这些苹果削皮、去核儿。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"苹果","en":"An apple is a round fruit with smooth green, yellow, or red skin and firm white flesh.","ex":{"en":"I want an apple.","cn":"我想要一个苹果。"}},{"pos":"PHRASE 短语","cn":"心肝宝贝；掌上明珠","en":"If you say that someone is the apple of your eye, you mean that they are very important to you and you are extremely fond of them.","ex":{"en":"Penny's only son was the apple of her eye.","cn":"彭妮的独子是她的心肝宝贝。"}}]},"examples":[{"en":"They are both great but you can't compare apples and oranges.","cn":"他们俩都很棒，但是截然不同，无法比较。"},{"en":"They really are apples and oranges.","cn":"他们确实是迥然不同。"}]},"appointment":{"media":{"uk":"media/uk/appointment__gb_1.mp3","us":"media/us/appointment__us_1.mp3"},"oxford":{"phon":"əˈpɔɪntmənt","pos":"noun","senses":[{"en":"a formal arrangement to meet or visit somebody at a particular time, especially for a reason connected with their work","cn":"约会；预约；约定","g":"[countable]","ex":{"en":"I've got a dental appointment at 3 o'clock.","cn":"我约了下午 3 点看牙医。"}},{"en":"the act of choosing a person for a job or position of responsibility; the fact of being chosen for a job, etc.","cn":"任命；委任","g":"[countable, uncountable]","ex":{"en":"They announced the appointments of key security officials.","cn":"他们宣布了重要安全官员的任命。"}},{"en":"a job or position of responsibility","cn":"职务；职位","g":"[countable]","lab":"especially British English","ex":{"en":"a permanent/first appointment","cn":"固定职位；第一次任职"}},{"en":"a person chosen for a job or position of responsibility","cn":"职务；职位","g":"[countable]","ex":{"en":"Government ministers and other political appointments are frequently replaced.","cn":"政府部长和其他政治任命经常被更换。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"任命；委派；指派","en":"The appointment of a person to a particular job is the choice of that person to do it.","ex":{"en":"His appointment to the Cabinet would please the right-wing.","cn":"他被任命为内阁成员会让右翼党派很高兴。"}},{"pos":"N-COUNT 可数名词","cn":"职位；职务","en":"An appointment is a job or position of responsibility.","ex":{"en":"Mr Fay is to take up an appointment as a researcher with the Royal Society.","cn":"费伊先生将担任皇家学会研究员的职务。"}},{"pos":"N-COUNT 可数名词","cn":"约会；约定","en":"If you have an appointment with someone, you have arranged to see them at a particular time, usually in connection with their work or for a serious purpose.","ex":{"en":"She has an appointment with her accountant","cn":"她和她的会计约好了见面。"}},{"pos":"PHRASE 短语","cn":"经过预约","en":"If something can be done by appointment, people can arrange in advance to do it at a particular time.","ex":{"en":"Viewing is by appointment only.","cn":"参观须事先预约。"}}]},"examples":[{"en":"She made an appointment for her son to see the doctor.","cn":"她为儿子约定了看医生的时间。"},{"en":"I've got a dental appointment at 3 o'clock.","cn":"我约了下午 3 点看牙医。"}]},"april":{"media":{"uk":"media/uk/april__gb_1.mp3","us":"media/us/april__us_1.mp3"},"oxford":{"phon":"ˈeɪprəl","pos":"noun","senses":[{"en":"the fourth month of the year, between March and May","cn":"四月","lab":"British English","ex":{"en":"She was born in April.","cn":"她是四月出生的。"}},{"en":"a first name for girls","cn":"阿葡丽尔（女子名）"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"四月","en":"April is the fourth month of the year in the Western calendar.","ex":{"en":"The changes will be introduced in April","cn":"这些变更将于4月开始实行。"}}]},"examples":[{"en":"( BrE ) The meeting is on the fifth of April/April the fifth.","cn":"会议日期是四月五日。"},{"en":"( NAmE ) The meeting is on April fifth.","cn":"会议日期是四月五日。"}]},"appreciate":{"oxford":{"phon":"əˈpriːʃieɪt","pos":"verb","senses":[{"en":"to recognize the good qualities of somebody/something","cn":"欣赏；赏识；重视","g":"[transitive]","ex":{"en":"Over the years he came to appreciate the beauty and tranquillity of the river.","cn":"经过这些年，他开始欣赏这条河的美丽和宁静。"}},{"en":"to be grateful for something that somebody has done; to welcome something","cn":"感激；感谢；欢迎","g":"[transitive]","ex":{"en":"I'd appreciate some help.","cn":"如果有人帮忙我将非常感激。"}},{"en":"to understand that something is true","cn":"理解；意识到；领会","g":"[transitive]","ex":{"en":"What I failed to appreciate was the distance between the two cities.","cn":"我没有意识到这两座城市间的距离。"}},{"en":"to increase in value over a period of time","cn":"增值；升值","g":"[intransitive]","ex":{"en":"Their investments have appreciated over the years.","cn":"他们的投资这些年来已经增值。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"欣赏；鉴赏；赏识","en":"If you appreciate something, for example a piece of music or good food, you like it because you recognize its good qualities.","ex":{"en":"Anyone can appreciate our music","cn":"任何人都能欣赏我们的音乐。"}},{"pos":"VERB 动词","cn":"领会；了解；认识","en":"If you appreciate a situation or problem, you understand it and know what it involves.","ex":{"en":"She never really appreciated the depth and bitterness of the Irish conflict","cn":"她从来没有真正认识到爱尔兰矛盾的深刻和激烈。"}},{"pos":"VERB 动词","cn":"感谢;感激","en":"If you appreciate something that someone has done for you or is going to do for you, you are grateful for it.","ex":{"en":"Peter stood by me when I most needed it. I'll always appreciate that","cn":"当我最需要的时候，彼得在我身边支持我。我将永存感激。"}},{"pos":"VERB 动词","cn":"升值；增值","en":"If something that you own appreciates over a period of time, its value increases.","ex":{"en":"They don't have any confidence that houses will appreciate in value.","cn":"他们完全不相信房子会升值。"}}]},"media":{"uk":"media/uk/appreciate__gb_1.mp3","us":"media/us/appreciate__us_1.mp3"},"examples":[{"en":"You can't really appreciate foreign literature in translation.","cn":"看翻译作品不能真正欣赏到外国文学原着的美妙之处。"},{"en":"His talents are not fully appreciated in that company.","cn":"他的才干在那家公司未受到充分赏识。"}]},"apprenticeship":{"media":{"uk":"media/uk/apprenticeship__gb_1.mp3","us":"media/us/apprenticeship__us_1.mp3"},"oxford":{"phon":"əˈprentɪʃɪp","pos":"noun","senses":[{"en":"a period of time working as an apprentice; a job as an apprentice","cn":"学徒期；学徒工作","ex":{"en":"She was in the second year of her apprenticeship as a carpenter.","cn":"她当木工学徒已是第二年了。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"学徒身份；学徒期","en":"Someone who has an apprenticeship works for a fixed period of time for a person who has a particular skill in order to learn the skill. Apprenticeship is the system of learning a skill like this.","ex":{"en":"After serving his apprenticeship as a toolmaker, he became a manager.","cn":"结束了工具匠的学徒期以后，他当上了经理。"}}]},"examples":[{"en":"She was in the second year of her apprenticeship as a carpenter.","cn":"她当木工学徒已是第二年了。"},{"en":"He had served his apprenticeship as a plumber.","cn":"他当过管子工学徒。"}]},"applications":{"oxford":{"phon":"ˌæplɪˈkeɪʃn","pos":"noun","senses":[{"en":"a formal (often written) request for sth, such as a job, permission to do sth or a place at a college or university","cn":"申请；请求；申请书；申请表"},{"en":"the practical use of sth, especially a theory, discovery, etc. （","cn":"尤指理论、发现等的）应用，运用"}]}},"appropriately":{"oxford":{"phon":"əˈprəʊpriətli","pos":"adverb","senses":[{"en":"in a way that is suitable, acceptable or correct for the particular circumstances","cn":"合适地；恰当地","ex":{"en":"The government has been accused of not responding appropriately to the needs of the homeless.","cn":"政府未采取适当的措施以回应无家可归者的需要，为此已受到谴责。"}}]},"media":{"uk":"media/uk/appropriately__gb_1.mp3","us":"media/us/appropriately__us_1.mp3"},"examples":[{"en":"The government has been accused of not responding appropriately to the needs of the homeless.","cn":"政府未采取恰当的措施以应无家可归者的需要，为此已受到谴责。"},{"en":"The chain of volcanoes is known, appropriately enough, as the ‘Ring of Fire’.","cn":"人们把这链状火山群很恰当地称作“火环”。"}]},"application":{"oxford":{"phon":"ˌæplɪˈkeɪʃn","pos":"noun","senses":[{"en":"a formal (often written) request for something, such as a job, permission to do something or a place at a college or university","cn":"申请；请求；申请书；申请表","g":"[countable, uncountable]","lab":"formal","sc":"for job/course","ex":{"en":"a planning/patent/visa application","cn":"规划／专利／签证申请"}},{"en":"the practical use of something, especially a theory, discovery, etc.","cn":"（尤指理论、发现等的）应用，运用","g":"[countable, uncountable]","sc":"practical use","ex":{"en":"The invention would have a wide range of applications in industry.","cn":"这项发明在工业中会有广泛用途。"}},{"en":"an act of putting or spreading something, such as paint or medical creams, onto something else","cn":"涂抹；敷用；施用","g":"[countable, uncountable]","sc":"of paint/cream","ex":{"en":"It took three applications of paint to cover the graffiti.","cn":"刷了三道油漆才盖住了涂鸦。"}},{"en":"the act of making a rule, etc. operate or become effective","cn":"运用；生效","g":"[uncountable]","sc":"of rule/law","ex":{"en":"strict application of the law","cn":"法律的严格执行"}},{"en":"a program designed to do a particular job; a piece of software","cn":"应用程序；应用软件","g":"[countable]","sc":"computing","ex":{"en":"a database application","cn":"数据库应用软件"}},{"en":"the strength of mind to work hard at something; great effort","cn":"勤奋；努力","g":"[uncountable]","lab":"formal","sc":"hard work","ex":{"en":"Success as a writer demands great application.","cn":"作家要成功就得悉力以赴。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"申请；请求；申请书；申请表","en":"An application for something such as a job or membership of an organization is a formal written request for it.","ex":{"en":"His application for membership of the organisation was rejected","cn":"他想要加入该组织的申请遭到了拒绝。"}},{"pos":"N-VAR 可变名词","cn":"应用；运用","en":"The application of a rule or piece of knowledge is the use of it in a particular situation.","ex":{"en":"Students learned the practical application of the theory they had learned in the classroom","cn":"学生们学会了将课堂上学到的理论付诸实际应用。"}},{"pos":"N-COUNT 可数名词","cn":"（计算机的）应用软件","en":"In computing, an application is a piece of software designed to carry out a particular task."},{"pos":"N-UNCOUNT 不可数名词","cn":"勤奋;专心;努力","en":"Application is hard work and concentration on what you are doing over a period of time.","ex":{"en":"...his immense talent, boundless energy and unremitting application.","cn":"他横溢的才华、充沛的精力和不懈的努力"}},{"pos":"N-VAR 可变名词","cn":"涂抹；敷用；施用","en":"The application of something to a surface is the act or process of putting it on or rubbing it into the surface.","ex":{"en":"With repeated applications of weedkiller, the weeds were overcome.","cn":"经过反复施用除草剂，杂草得以彻底根除。"}}]},"media":{"uk":"media/uk/application__gb_1.mp3","us":"media/us/application__us_1.mp3"},"examples":[{"en":"Further information is available on application to the principal.","cn":"可向校长提交申请书索取更多信息。"},{"en":"The invention would have a wide range of applications in industry.","cn":"这项发明在工业中会有广泛用途。"}]},"apprentices":{"oxford":{"phon":"əˈprentɪs","pos":"noun","senses":[{"en":"a young person who works for an employer for a fixed period of time in order to learn the particular skills needed in their job","cn":"学徒；徒弟"},{"en":"( old-fashioned ) to make sb an apprentice","cn":"使某人当（某人的）学徒"}]}},"apartment":{"media":{"uk":"media/uk/apartment__gb_1.mp3","us":"media/us/apartment__us_1.mp3"},"oxford":{"phon":"əˈpɑːtmənt","pos":"noun","senses":[{"en":"a set of rooms for living in, usually on one floor of a building","cn":"（通常指在同一楼层的）公寓套房","lab":"especially North American English","ex":{"en":"an apartment building","cn":"公寓楼"}},{"en":"a set of rooms used for a holiday","cn":"（度假用的）公寓套房","ex":{"en":"self-catering holiday apartments","cn":"自己开伙的度假套房"}},{"en":"a room in a house, especially a large or famous house","cn":"（尤指巨屋、名宅的）房间","g":"[usually plural]","lab":"British English","ex":{"en":"You can visit the whole palace except for the private apartments.","cn":"整座宫殿除内殿外均可参观。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指在同一楼层的）公寓套房","en":"An apartment is a set of rooms for living in, usually on one floor of a large building.","ex":{"en":"Christina has her own apartment, with her own car.","cn":"克里斯蒂娜有自己的公寓和汽车。"}},{"pos":"N-PLURAL 复数名词","cn":"（国王、王后、总统等要人居住的）套间，套房","en":"The apartments of an important person such as a king, queen, or president are a set of large rooms which are used by them.","ex":{"en":"...the private apartments of the Prince of Wales at St James's Palace.","cn":"威尔士亲王在圣詹姆斯宫的私人套房"}}]},"examples":[{"en":"You can visit the whole palace except for the private apartments.","cn":"整座宫殿除内殿外均可参观。"},{"en":"self-catering holiday apartments","cn":"自己开伙的度假租房"}]},"apartments":{"oxford":{"phon":"əˈpɑːtmənt","pos":"noun","senses":[{"en":"( especially NAmE ) a set of rooms for living in, usually on one floor of a building （","cn":"通常指在同一楼层的）公寓套房"},{"en":"a set of rooms used for a holiday/vacation （","cn":"度假用的）公寓套房"}]},"media":{"uk":"media/uk/apartment__gb_1.mp3","us":"media/us/apartment__us_1.mp3"}},"app":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of computer software that does a particular job","cn":"应用程序﹐应用软件"}]},"examples":[{"en":"You can download an app that reminds you of things you have to do.","cn":"你可以下载一个应用，提醒自己必须要做的事项。","src":"ld"}],"media":{"uk":"media/uk/app__gb_1.mp3","us":"media/us/app__us_1.mp3"},"oxford":{"phon":"æp","pos":"noun","senses":[{"en":"a piece of software that you can download to a device such as a smartphone or tablet, for example to look up information or to play a game","cn":"（下载到智能手机或平板电脑等设备上使用的）应用软件","ex":{"en":"You first need to install the app on your device.","cn":"首先要把这个应用软件安装到你的设备上。"}},{"en":"a program designed to do a particular job; a piece of software","cn":"应用程序；应用软件","ex":{"en":"a database app","cn":"数据库应用程序"}}]}},"appreciative":{"media":{"uk":"media/uk/appreciative__gb_1.mp3","us":"media/us/appreciative__us_1.mp3"},"oxford":{"phon":"əˈpriːʃətɪv","pos":"adjective","senses":[{"en":"feeling or showing that you are grateful for something","cn":"感激的；感谢的","ex":{"en":"The company was very appreciative of my efforts.","cn":"公司对我的努力十分赞赏。"}},{"en":"showing pleasure","cn":"欣赏的；赏识的","ex":{"en":"an appreciative audience/smile","cn":"有欣赏力的观众；会意的微笑"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"欣赏的;赏识的;赞赏的","en":"An appreciative reaction or comment shows the enjoyment that you are getting from something.","ex":{"en":"There is a murmur of appreciative laughter","cn":"发出一阵赞赏的低笑声。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"感谢的；感激的","en":"If you are appreciative of something, you are grateful for it.","ex":{"en":"We have been very appreciative of their support","cn":"我们对他们的支持一直心存感激。"}}]},"examples":[{"en":"The company was very appreciative of my efforts.","cn":"公司对我的努力十分赞赏。"},{"en":"an appreciative audience/smile","cn":"有欣赏力的观众；会意的微笑"}]},"apparent":{"media":{"uk":"media/uk/apparent__gb_1.mp3","us":"media/us/apparent__us_1.mp3"},"oxford":{"phon":"əˈpærənt","pos":"adjective","senses":[{"en":"easy to see or understand","cn":"显而易见；明白易懂；显然","g":"[not usually before noun]","ex":{"en":"Their devotion was apparent.","cn":"他们的忠诚显而易见。"}},{"en":"that seems to be real or true but may not be","cn":"貌似的；表面上的；未必真实的","g":"[usually before noun]","ex":{"en":"My parents were concerned at my apparent lack of enthusiasm for school.","cn":"我看起来对上学不感兴趣，父母为此担心。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"貌似的；表面上的；似乎真实的","en":"An apparent situation, quality, or feeling seems to exist, although you cannot be certain that it does exist.","ex":{"en":"I was a bit depressed by our apparent lack of progress","cn":"我对我们看似缓慢的进展感到有些沮丧。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明显的；显而易见的","en":"If something is apparent to you, it is clear and obvious to you.","ex":{"en":"It has been apparent that in other areas standards have held up well","cn":"显然，这些标准在其他地区执行得很好。"}},{"pos":"PHRASE 短语","cn":"原因不明；不知何故","en":"If you say that something happens for no apparent reason, you cannot understand why it happens.","ex":{"en":"The person may become dizzy for no apparent reason.","cn":"这类人可能会莫名其妙地感到头晕。"}}]},"examples":[{"en":"Then, for no apparent reason, the train suddenly stopped.","cn":"接着，不知什么原因，火车突然停了下来。"},{"en":"It was apparent from her face that she was really upset.","cn":"从面容上一眼就可以看出她确实心绪烦乱。"}]},"apply":{"media":{"uk":"media/uk/apply__gb_1.mp3","us":"media/us/apply__us_1.mp3"},"oxford":{"phon":"əˈplaɪ","pos":"verb","senses":[{"en":"to make a formal request, usually in writing, for something such as a job, a loan, permission for something, a place at a university, etc.","cn":"（通常以书面形式）申请，请求","g":"[intransitive, transitive]","sc":"for job/course","ex":{"en":"You should apply in person/by letter.","cn":"你应该当面／写信申请。"}},{"en":"to affect or be relevant to somebody/something","cn":"有关；涉及","g":"[intransitive, transitive]","sc":"be relevant","ex":{"en":"Special conditions apply if you are under 18.","cn":"18 岁以下者按特殊情况处理。"}},{"en":"to use something or make something work in a particular situation","cn":"使用；应用","g":"[transitive]","sc":"use","ex":{"en":"to apply political pressure","cn":"施加政治压力"}},{"en":"to put or spread something such as paint, cream, etc. onto a surface","cn":"涂；敷；施","g":"[transitive]","sc":"paint/cream","ex":{"en":"Apply the cream sparingly to your face and neck.","cn":"把乳霜薄薄地抹在脸和脖子上。"}},{"en":"to work at something or study something very hard","cn":"勤奋工作；努力学习","g":"[transitive]","sc":"work hard","ex":{"en":"You would pass your exams if you applied yourself.","cn":"努力学习就会通过考试。"}},{"en":"to press on something hard with your hand, foot, etc. to make something work or have an effect on something","cn":"手压；脚踩","g":"[transitive]","sc":"press hard","ex":{"en":"to apply the brakes (of a vehicle)","cn":"踩刹车"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"申请;请求","en":"If you apply for something such as a job or membership of an organization, you write a letter or fill in a form in order to ask formally for it.","ex":{"en":"I am continuing to apply for jobs","cn":"我正在继续找工作。"}},{"pos":"VERB 动词","cn":"使（自己）全神贯注于；使（注意力等）集中于","en":"If you apply yourself to something or apply your mind to something, you concentrate hard on doing it or on thinking about it.","ex":{"en":"Faulks has applied himself to this task with considerable energy","cn":"福克斯为这项任务倾注了大量精力。"}},{"pos":"VERB 动词","cn":"适用;适合","en":"If something such as a rule or a remark applies to a person or in a situation, it is relevant to the person or the situation.","ex":{"en":"The convention does not apply to us","cn":"这条惯例对我们不适用。"}},{"pos":"VERB 动词","cn":"应用;运用","en":"If you apply something such as a rule, system, or skill, you use it in a situation or activity.","ex":{"en":"The Government appears to be applying the same principle","cn":"政府似乎是在运用相同的原则。"}},{"pos":"VERB 动词","cn":"将（名字等）用于","en":"A name that is applied to someone or something is used to refer to them.","ex":{"en":"Connell said a new medical term should be applied to Berg's actions. He calls it 'medicide'.","cn":"康奈尔说应该用一个新的医学名词描述伯格的行为。他称之为“医生协助自杀”。"}},{"pos":"VERB 动词","cn":"涂抹；敷用；施用","en":"If you apply something to a surface, you put it on or rub it into the surface.","ex":{"en":"The right thing would be to apply direct pressure to the wound","cn":"正确的做法是直接按住伤口。"}},{"pos":"VERB 动词","cn":"踩（刹车）","en":"When the driver of a vehicle applies the brakes, he or she uses them to slow the vehicle down or to stop it from moving.","ex":{"en":"They forgot to apply the handbrake and the car rolled 60ft into the river.","cn":"他们忘了拉手刹，汽车翻滚了60英尺，掉进了河里。"}}]},"examples":[{"en":"The word ‘unexciting’ could never be applied to her novels. “","cn":"乏味”这个词绝对和她的小说沾不上边儿。"},{"en":"We applied our minds to finding a solution to our problem.","cn":"我们绞尽脑汁寻求解决问题的办法。"}]},"appealing":{"media":{"uk":"media/uk/appealing__gb_1.mp3","us":"media/us/appealing__us_1.mp3"},"oxford":{"phon":"əˈpiːlɪŋ","pos":"adjective","senses":[{"en":"attractive or interesting","cn":"有吸引力的；有感染力的；令人感兴趣的","ex":{"en":"Spending the holidays in Britain wasn't a prospect that I found particularly appealing.","cn":"在英国度假对我并不特别有吸引力。"}},{"en":"showing that you want people to help you or to show you sympathy","cn":"恳求的；可怜的；希望同情的","ex":{"en":"‘Would you really help?’ he said with an appealing look.","cn":"“你真的愿意帮忙吗？”他恳求道。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有吸引力的;有趣的;动人的","en":"Someone or something that is appealing is pleasing and attractive.","ex":{"en":"There was a sense of humour to what he did that I found very appealing","cn":"他举手投足间流露出一种幽默感，我觉得很有魅力。"}},{"pos":"ADJ 形容词","cn":"（表情、语气）恳求的，哀求的","en":"An appealing expression or tone of voice indicates to someone that you want help, advice, or approval.","ex":{"en":"She gave him a soft appealing look that would have melted solid ice.","cn":"她恳求地看了他一眼，温柔的眼神足以融化坚冰。"}}]},"examples":[{"en":"‘Would you really help?’ he said with an appealing look. “","cn":"你真的愿意帮忙吗？”他满脸恳求地说。"},{"en":"Spending the holidays in Britain wasn't a prospect that I found particularly appealing.","cn":"在英国度假对我并不特别有吸引力。"}]},"appeals":{"oxford":{"phon":"əˈpiːl","pos":"noun","senses":[{"en":"a formal request to a court or to sb in authority for a judgement or a decision to be changed","cn":"上诉；申诉"},{"en":"a quality that makes sb/sth attractive or interesting","cn":"吸引力；感染力；魅力"}]}},"approaching":{"oxford":{"phon":"əˈprəʊtʃ","pos":"verb","senses":[{"en":"to come near to sb/sth in distance or time （","cn":"在距离或时间上）靠近，接近"},{"en":"to speak to sb about sth, especially to ask them for sth or to offer to do sth","cn":"接洽；建议；要求"}]}},"appealed":{"oxford":{"phon":"əˈpiːl","pos":"noun","senses":[{"en":"a formal request to a court or to sb in authority for a judgement or a decision to be changed","cn":"上诉；申诉"},{"en":"a quality that makes sb/sth attractive or interesting","cn":"吸引力；感染力；魅力"}]}},"applauded":{"oxford":{"phon":"əˈplɔːd","pos":"verb","senses":[{"en":"to show your approval of sb/sth by clapping your hands","cn":"鼓掌"},{"en":"( formal ) to express praise for sb/sth because you approve of them or it","cn":"称赞；赞许；赞赏"}]}},"apprenticeships":{"oxford":{"phon":"əˈprentɪʃɪp","pos":"noun","senses":[{"en":"a period of time working as an apprentice; a job as an apprentice","cn":"学徒期；学徒工作"}]}},"approaches":{"oxford":{"phon":"əˈprəʊtʃ","pos":"verb","senses":[{"en":"to come near to sb/sth in distance or time （","cn":"在距离或时间上）靠近，接近"},{"en":"to speak to sb about sth, especially to ask them for sth or to offer to do sth","cn":"接洽；建议；要求"}]}},"appears":{"oxford":{"phon":"əˈpɪə(r)","pos":"verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) to give the impression of being or doing sth 显得；看来；似乎"},{"en":"to start to be seen","cn":"出现；呈现；显现"}]}},"appliances":{"oxford":{"phon":"əˈplaɪəns","pos":"noun","senses":[{"en":"a machine that is designed to do a particular thing in the home, such as preparing food, heating or cleaning （","cn":"家用）电器，器具"}]},"media":{"img":["media/pic/appliances_comp.jpg"]}},"appearing":{"oxford":{"phon":"əˈpɪə(r)","pos":"verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) to give the impression of being or doing sth 显得；看来；似乎"},{"en":"to start to be seen","cn":"出现；呈现；显现"}]}},"appeared":{"oxford":{"phon":"əˈpɪə(r)","pos":"verb","senses":[{"en":"( not used in the progressive tenses","cn":"不用于进行时 ) to give the impression of being or doing sth 显得；看来；似乎"},{"en":"to start to be seen","cn":"出现；呈现；显现"}]}},"applicants":{"oxford":{"phon":"ˈæplɪkənt","pos":"noun","senses":[{"en":"a person who makes a formal request for sth (= applies for it), especially for a job, a place at a college or university, etc.","cn":"申请人（尤指求职、进高等学校等）"}]}},"approached":{"oxford":{"phon":"əˈprəʊtʃ","pos":"verb","senses":[{"en":"to come near to sb/sth in distance or time （","cn":"在距离或时间上）靠近，接近"},{"en":"to speak to sb about sth, especially to ask them for sth or to offer to do sth","cn":"接洽；建议；要求"}]}},"apologetic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"表示歉意的；认错的；愧疚的","en":"If you are apologetic, you show or say that you are sorry for causing trouble for someone, for hurting them, or for disappointing them.","ex":{"en":"The hospital staff were very apologetic but that couldn't really compensate","cn":"医院的工作人员深表歉意，但这真的于事无补。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"to tell someone you are sorry that you have upset them or done something that causes problems for them","cn":""},{"en":"to tell someone that you are sorry you have upset them or done something bad","cn":""},{"en":"to tell someone that you are sorry, especially in a formal situation or when you do not know the person well","cn":""}]},"vocab":{"pos":"adj","senses":[{"en":"If you're apologetic , you're very sorry about something. You might offer an apologetic smile at another driver if you accidentally honk at her."}]},"collocations":{"phrases":["VERBS be, feel, look, sound","ADV. profusely, very | almost Barney sounded almost apologetic. | faintly, slightly, vaguely | suitably I hope she was suitably apologetic a","PREP. about He was profusely apologetic about the mistake. | for She was apologetic for taking so long."]},"media":{"uk":"media/ldoce/hwd/bre/d/apologetic0205.mp3","us":"media/ldoce/hwd/ame/2/apologetic.mp3"},"examples":[{"en":"‘I'm sorry I'm late,’ he murmured apologetically. “","cn":"对不起，我迟到了。”他小声道歉说。"},{"en":"‘Sorry,’ she said, with an apologetic smile. “","cn":"对不起。”她说，歉然一笑。"}],"oxford":{"phon":"əˌpɒləˈdʒetɪk","pos":"adjective","senses":[{"en":"feeling or showing that you are sorry for doing something wrong or for causing a problem","cn":"道歉的；谢罪的；愧疚的","ex":{"en":"‘Sorry,’ she said, with an apologetic smile.","cn":"“对不起。”她说，歉然一笑。"}}]}},"apology":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"道歉；认错；愧疚的表示","en":"An apology is something that you say or write in order to tell someone that you are sorry that you have hurt them or caused trouble for them.","ex":{"en":"I didn't get an apology","cn":"还没有向我道歉。"}},{"pos":"N-PLURAL 复数名词","cn":"（表示或作出）道歉","en":"If you offer or make your apologies, you apologize.","ex":{"en":"His mother offered her apologies to the Jones family","cn":"他的母亲向琼斯一家赔了不是。"}},{"pos":"PHRASE 短语","cn":"（对某事）无可道歉，无错可认","en":"If you say that you make no apologies for what you have done, you are emphasizing that you feel that you have done nothing wrong.","ex":{"en":"Union officials made no apologies for the threatened chaos.","cn":"工会干部们对于迫在眉睫的混乱局面不予道歉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to tell someone you are sorry that you have upset them or done something that causes problems for them","cn":""},{"en":"to tell someone that you are sorry you have upset them or done something bad","cn":""},{"en":"to tell someone that you are sorry, especially in a formal situation or when you do not know the person well","cn":""}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"An apology is what you say or do when you want to let someone know (or fool them into thinking) that you regret something. An apology is nice, but chocolates or large bundles of cash are nicer. Always."}]},"collocations":{"phrases":["ADJ. abject, humble, profuse It was a mistake. My profuse apologies. | heartfelt, profound, sincere | full | formal | public | written","VERB + APOLOGY convey, give sb, issue, make, offer (sb), publish, send (sb) The newpaper has issued an apology to the minister. | get, recei","PREP. without ~ He backed out arrogantly and without apology. | ~ for an apology for arriving late | ~ from Apologies have been received fro","PHRASES a letter of apology, make no apology/apologies for I make no apologies for bringing this issue to your attention once again."]},"media":{"uk":"media/ldoce/hwd/bre/3/apology0205.mp3","us":"media/ldoce/hwd/ame/3/apology.mp3"},"examples":[{"en":"The meeting started with apologies (= the names of people who said they could not go to the meeting).","cn":"会议一开始就宣布了请假缺席者的名单。"},{"en":"You owe him an apology for what you said.","cn":"你要为你所说的话向他道歉。"}],"oxford":{"phon":"əˈpɒlədʒi","pos":"noun","senses":[{"en":"a word or statement saying sorry for something that has been done wrong or that causes a problem","cn":"道歉；谢罪","g":"[countable, uncountable]","ex":{"en":"to offer/make/demand/accept an apology","cn":"主动道歉；致歉；要求／接受道歉"}},{"en":"information that you cannot go to a meeting or must leave early","cn":"（因不能赴会或提前离会的）致歉","g":"[countable, usually plural]","lab":"formal","ex":{"en":"The meeting started with apologies (= the names of people who said they could not go to the meeting).","cn":"会议一开始就宣布了请假缺席者的名单。"}}]}},"appendicitis":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"阑尾炎;盲肠炎","en":"Appendicitis is an illness in which a person's appendix is infected and painful.","ex":{"en":"He is recovering in hospital after an operation for acute appendicitis.","cn":"做完急性阑尾炎手术后，他正在医院康复。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an illness in which your appendix swells and causes pain","cn":"阑尾炎"}]},"vocab":{"pos":"n","senses":[{"en":"Appendicitis is a painful medical condition caused by a swollen appendix. To keep the appendix from bursting, doctors often perform surgery to remove the appendix of patients who have appendicitis ."}]},"collocations":{"phrases":["ADJ. acute | suspected","QUANT. case","VERB + APPENDICITIS have | get | diagnose •"]},"media":{"uk":"media/ldoce/hwd/bre/3/appendicitis0205.mp3","us":"media/ldoce/hwd/ame/4/appendicitis.mp3"},"oxford":{"phon":"əˌpendəˈsaɪtɪs","pos":"noun","senses":[{"en":"a serious medical condition in which the appendix becomes painful and larger than normal","cn":"阑尾炎"}]}},"appraisal":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"评价；评估；估量","en":"If you make an appraisal of something, you consider it carefully and form an opinion about it.","ex":{"en":"What is needed in such cases is a calm appraisal of the situation","cn":"在此类情况下需要对形势有一个冷静的评估。"}},{"pos":"N-VAR 可变名词","cn":"（官方或正式的常带考核性质的）评定，评价","en":"Appraisal is the official or formal assessment of the strengths and weaknesses of someone or something. Appraisal often involves observation or some kind of testing.","ex":{"en":"Staff problems should be addressed through training and appraisals.","cn":"职员问题应该通过培训和考核评定来解决。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a statement or opinion judging the worth, value, or condition of something","cn":"评价﹔估计﹔鉴定"},{"en":"a meeting between a manager and a worker to discuss the quality of someone’s work and how well they do their job","cn":"员工工作评估﹐工作表现评估"}]},"vocab":{"pos":"n","senses":[{"en":"An appraisal is a judgment of something, especially an estimate of how much it's worth. Usually you need an expert to give an official appraisal ."}]},"collocations":{"phrases":["ADJ. detailed, full, thorough A detailed appraisal of the scheme will now be carried out. | frank, honest, realistic | independent | critica","VERB + APPRAISAL carry out, give, make He was asked to give an independent appraisal. She made a quick appraisal of the other guests.","APPRAISAL + NOUN interview We are holding staff appraisal interviews."]},"media":{"uk":"media/ldoce/hwd/bre/2/appraisal0205.mp3","us":"media/ldoce/hwd/ame/0/appraisal.mp3"},"examples":[{"en":"He had read many detailed critical appraisals of her work.","cn":"他读了许多详细评论她的作品的文章。"},{"en":"She was honest in her appraisal of her team's chances.","cn":"她对自己队获胜机会的估计是中肯的。"}],"oxford":{"phon":"əˈpreɪzl","pos":"noun","senses":[{"en":"a judgement of the value, performance or nature of somebody/something","cn":"评价；估价；估计；鉴定","ex":{"en":"He had read many detailed critical appraisals of her work.","cn":"他读了许多详细评论她的作品的文章。"}},{"en":"a meeting in which an employee discusses with their manager how well they have been doing their job; the system of holding such meetings","cn":"（上司对雇员的）工作鉴定会；工作表现评估","lab":"especially British English","ex":{"en":"I have my appraisal today.","cn":"我今天与上司见面讨论我的工作表现。"}}]}},"apologize":{"collins":{"senses":[{"pos":"VERB 动词","cn":"道歉；认错","en":"When you apologize to someone, you say that you are sorry that you have hurt them or caused trouble for them. You can say 'I apologize' as a formal way of saying sorry.","ex":{"en":"Two years ago, Congress formally apologized for the internment","cn":"两年前，国会就此拘留事件正式道歉。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to tell someone you are sorry that you have upset them or done something that causes problems for them","cn":""},{"en":"to tell someone that you are sorry you have upset them or done something bad","cn":""},{"en":"to tell someone that you are sorry, especially in a formal situation or when you do not know the person well","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"When you apologize you admit that you did something wrong, and you say you’re sorry. The point of apologizing is usually to clear the slate and explain why you did what you did."}]},"collocations":{"phrases":["ADV. sincerely | profusely He apologized profusely for the damage he had caused. | humbly I do apologize most humbly. | publicly","VERB + APOLOGIZE ought to, should | want to, wish to, would like to I would like to apologize most sincerely for any embarrassment caused.","PREP. for She apologized for being late. | to He apologized to his colleagues.","PHRASES I do/must apologize I must apologize for cancelling our meeting at such short notice."]},"media":{"uk":"media/ldoce/hwd/bre/6/apologize0205.mp3","us":"media/ldoce/hwd/ame/6/laadapologize.mp3"},"examples":[{"en":"We apologize for the late departure of this flight.","cn":"本航班延误离境，谨致歉意。"},{"en":"Why should I apologize?","cn":"我为什么要道歉？"}],"oxford":{"phon":"əˈpɒlədʒaɪz","pos":"verb","senses":[{"en":"to say that you are sorry for doing something wrong or causing a problem","cn":"道歉；谢罪","ex":{"en":"Why should I apologize?","cn":"我为什么要道歉？"}}]}},"applaud":{"collins":{"senses":[{"pos":"VERB 动词","cn":"鼓掌（以示赞赏）","en":"When a group of people applaud, they clap their hands in order to show approval, for example when they have enjoyed a play or concert.","ex":{"en":"The audience laughed and applauded","cn":"观众边笑边鼓掌。"}},{"pos":"VERB 动词","cn":"称赞；赞许","en":"When an attitude or action is ap-plauded, people praise it.","ex":{"en":"He should be applauded for his courage","cn":"他的勇气值得称道。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to say that you admire and approve of someone or something, especially publicly","cn":""},{"en":"to tell someone that you think it is good that they have achieved something","cn":""},{"en":"to say to someone that you like how they look, or you like something they have done","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"To applaud is to show approval, encouragement, or appreciation. You can applaud by clapping your hands at a performance, or you can applaud with just your mouth, as when you tell someone \"I applaud your decision to start exercising.\""}]},"collocations":{"phrases":["ADV. loudly The audience applauded loudly. 2 praise sb/sth","ADV. strongly, warmly The decision to save the company has been warmly applauded.","PHRASES is to be applauded, should be applauded His efforts to help people should be applauded."]},"media":{"uk":"media/ldoce/hwd/bre/5/applaud0205.mp3","us":"media/ldoce/hwd/ame/a/applaud.mp3"},"examples":[{"en":"His efforts to improve the situation are to be applauded.","cn":"他为改善状况所作的努力应该受到赞许。"},{"en":"He started to applaud and the others joined in.","cn":"他开始鼓掌，其他人也跟着鼓起掌来。"}],"oxford":{"phon":"əˈplɔːd","pos":"verb","senses":[{"en":"to show your approval of somebody/something by clapping your hands (= hitting your open hands together several times)","cn":"鼓掌","g":"[intransitive, transitive]","ex":{"en":"He started to applaud and the others joined in.","cn":"他开始鼓掌，其他人也跟着鼓起掌来。"}},{"en":"to express praise for somebody/something because you approve of them or it","cn":"称赞；赞许；赞赏","g":"[transitive]","lab":"formal","ex":{"en":"We applaud her decision.","cn":"我们称赞她的决定。"}}]}},"applicable":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"适用的；适当的；可实施的","en":"Something that is applicable to a particular situation is relevant to it or can be applied to it.","ex":{"en":"What is a reasonable standard for one family is not applicable for another","cn":"对一个家庭合理的标准并不适用于另一个家庭。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"if something is applicable to a particular person, group, or situation, it affects them or is related to them","cn":"适合的﹐适用的"},{"en":"→ apply applicable to The offer is only applicable to bookings for double rooms.","cn":"这个报价只适用于预订双人房。 where/if/as applicable Ms/Miss/Mrs/Mr Please delete as applicable. 女士/小姐/太太/先生 请删去不适用项。"}]},"vocab":{"pos":"adj","senses":[{"en":"If something's applicable , it matters in a certain case: it's relevant. If we're going to have rules, shouldn't they be applicable to everyone?"}]},"collocations":{"phrases":["VERBS be, prove, seem new developments in research that could prove directly applicable to the treatment of some cancers | become | make sth","ADJ. broadly, generally, widely | universally | directly | immediately | equally The rules have now been made equally applicable to all memb","PREP. for The offer is only applicable for journeys made during the week. | to The law is applicable to everyone."]},"media":{"uk":"media/ldoce/hwd/bre/f/applicable0205.mp3","us":"media/ldoce/hwd/ame/8/applicable.mp3"},"examples":[{"en":"The new approach had wide applicability to all sorts of different problems.","cn":"新方法广泛适用于解决各种各样的问题。"},{"en":"Much of the form was not applicable (= did not apply) to me.","cn":"表格中很多部分不适用于我。"}],"oxford":{"phon":"əˈplɪkəbl","pos":"adjective","senses":[{"en":"that can be said to be true in the case of somebody/something","cn":"适用；合适","ex":{"en":"Give details of children where applicable (= if you have any).","cn":"如有子女请提供详情。"}}]}},"applicant":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"申请人（尤指提交正式书面申请的求职或求学的人）","en":"An applicant for something such as a job or a place at a college is someone who makes a formal written request to be given it."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to write to someone asking for something such as a job, an opportunity to study at a university, or permission to do something","cn":""},{"en":"to ask for something, especially money, from a government, company etc, because you believe you have a legal right to have it","cn":""},{"en":"to officially ask someone for something or ask someone to do something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An applicant is someone who signs up or applies for something. A job applicant for example, often fills out a form and then interviews for the position she hopes to get."}]},"collocations":{"phrases":["ADJ. potential, prospective | suitable, suitably qualified Grant payments will be made to suitable applicants. | unsuitable | lucky, success","VERB + APPLICANT attract The advertisement attracted a number of applicants. | shortlist Eighteen applicants were shortlisted. | interview |","APPLICANT + VERB apply All applicants should apply in writing.","PREP. ~ for There were over fifty applicants for the job."]},"media":{"uk":"media/ldoce/hwd/bre/b/applicant0205.mp3","us":"media/ldoce/hwd/ame/d/applicant.mp3"},"examples":[{"en":"There were over 500 applicants for the job.","cn":"有 500 多人申请这份工作。"}],"oxford":{"phon":"ˈæplɪkənt","pos":"noun","senses":[{"en":"a person who makes a formal request for something (= applies for it), especially for a job, a place at a college or university, etc.","cn":"申请人（尤指求职、进高等学校等）","ex":{"en":"There were over 500 applicants for the job.","cn":"有 500 多人申请这份工作。"}}]}},"appendix":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"阑尾；盲肠","en":"Your appendix is a small closed tube inside your body which is attached to your digestive system.","ex":{"en":"...a burst appendix.","cn":"阑尾穿孔"}},{"pos":"N-COUNT 可数名词","cn":"（书末的）附录","en":"An appendix to a book is extra information that is placed after the end of the main text."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small organ near your bowel , which has little or no use","cn":"阑尾"},{"en":"a part at the end of a book containing additional information 〔","cn":"书末的〕附录"}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"No, it's not just a tiny organ pouch that requires surgery when it begins to hurt; an appendix is also additional material at the end of a book or paper."}]},"collocations":{"phrases":["ADJ. burst, grumbling (= painful from time to time), inflamed, perforated, ruptured He was taken to hospital with a burst appendix.","VERB + APPENDIX remove, take out Doctors had to take out his appendix. | have out She might have to have her appendix out.","APPENDIX + VERB burst, rupture If the condition is not treated, the appendix can rupture."]},"media":{"uk":"media/ldoce/hwd/bre/9/appendix0205.mp3","us":"media/ldoce/hwd/ame/2/appendix.mp3"},"examples":[{"en":"He had to have his appendix out (= removed).","cn":"他不得不切除了阑尾。"},{"en":"Full details are given in Appendix 3.","cn":"详情见附录 3。"}],"oxford":{"phon":"əˈpendɪks","pos":"noun","senses":[{"en":"a small bag of tissue that is attached to the large intestine. In humans, the appendix has no clear function.","cn":"阑尾","ex":{"en":"He had to have his appendix out (= removed).","cn":"他不得不切除了阑尾。"}},{"en":"a section giving extra information at the end of a book or document","cn":"（书、文件的）附录","ex":{"en":"Full details are given in Appendix 3.","cn":"详见附录 3。"}}]}},"applause":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"掌声;喝彩","en":"Applause is the noise made by a group of people clapping their hands to show approval.","ex":{"en":"They greeted him with thunderous applause.","cn":"他们以雷鸣般的掌声欢迎他。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to hit your hands together loudly and quickly to show that you approve of and are pleased with a play, someone's performance, someone's actions etc","cn":""},{"en":"if people applaud , they clap excitedly, and often for a long time, in order to show how much they liked something or to show their support for someone","cn":""},{"en":"to give a loud, happy shout expressing admiration, approval, and often excitement, for example at a sports event or after a speech","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"After a theatrical performance, audience members typically use applause , or hand-clapping, to express their approval. (Of course, sometimes applause just means the audience is glad it’s time to go home.)"}]},"collocations":{"phrases":["ADJ. deafening, loud, thunderous, tumultuous | enthusiastic, rapturous, warm, wild | prolonged, sustained | spontaneous a little burst of sp","QUANT. burst, ripple, roar, round The crowd gave them a round of applause.","VERB + APPLAUSE be greeted with, draw, earn, get, receive, win The speech drew loud applause. | break into, burst into The audience broke in","APPLAUSE + VERB break out, greet sb/sth A great roar of applause broke out. Wild applause greeted this remark. | grow | die away/down, subsi","PREP. to ~ He left the stage to thunderous applause. | ~ for There was a ripple of applause for the speaker."]},"media":{"uk":"media/ldoce/hwd/bre/0/applause0205.mp3","us":"media/ldoce/hwd/ame/0/applause.mp3"},"examples":[{"en":"The audience broke into rapturous applause.","cn":"听众中爆发出一片欢呼喝彩声。"},{"en":"Give her a big round of applause!","cn":"为她热烈鼓掌！"}],"oxford":{"phon":"əˈplɔːz","pos":"noun","senses":[{"en":"the noise made by a group of people clapping their hands and sometimes shouting to show their approval or pleasure","cn":"鼓掌；喝彩","lab":"figurative","ex":{"en":"Give her a big round of applause!","cn":"为她热烈鼓掌！"}}]}},"appalling":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人震惊的；使人惊骇的；极为恶劣的","en":"Something that is appalling is so bad or unpleasant that it shocks you.","ex":{"en":"They have been living under the most appalling conditions for two months.","cn":"他们已经在恶劣不堪的条件下生活两个月了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"非常的;极其严重的","en":"You can use appalling to emphasize that something is very great or severe.","ex":{"en":"I developed an appalling headache.","cn":"我头痛欲裂。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very bad","cn":"极坏的﹐糟透的"},{"en":"very bad and unpleasant – used especially when something has a strong effect on you and you feel shocked, annoyed, or sick","cn":""},{"en":"terrible – especially in a way that is shocking. Appalling is stronger and a little more formal than terrible or horrible","cn":""}]},"vocab":{"pos":"adj n","senses":[{"en":"Something that is appalling is awful or horrible, causing dismay or disgust. It's definitely not appealing."}]},"collocations":{"phrases":["VERBS be, look, sound","ADV. really, truly | absolutely, the most, quite, utterly They had to wait for hours in the most appalling weather."]},"media":{"uk":"media/ldoce/hwd/bre/6/brelasdeappalling.mp3","us":"media/ldoce/hwd/ame/1/appalling.mp3"},"examples":[{"en":"The prisoners were living in appalling conditions.","cn":"囚犯的居住条件极为恶劣。"},{"en":"The bus service is appalling now.","cn":"现在公共汽车服务很差。"}],"oxford":{"phon":"əˈpɔːlɪŋ","pos":"adjective","senses":[{"en":"extremely bad, especially from a moral point of view","cn":"令人惊骇的；令人发指的","lab":"North American English, formal or British English，，","ex":{"en":"The prisoners were living in appalling conditions.","cn":"囚犯的居住条件极为恶劣。"}},{"en":"very bad; of very poor quality","cn":"糟糕的；质量极差的","lab":"informal","ex":{"en":"The bus service is appalling now.","cn":"现在公共汽车服务很差。"}}]}},"apprehension":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"担心；忧虑；恐惧","en":"Apprehension is a feeling of fear that something bad may happen.","ex":{"en":"It reflects real anger and apprehension about the future","cn":"它反映出对未来真实的愤怒和恐惧。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"逮捕；拘押","en":"The apprehension of someone who is thought to be a criminal is their capture or arrest by the police.","ex":{"en":"...information leading to the apprehension of the alleged killer.","cn":"致使凶杀嫌犯被捕的信息"}},{"pos":"N-UNCOUNT 不可数名词","cn":"理解;领悟","en":"The apprehension of something is awareness and understanding of it.","ex":{"en":"...the sudden apprehension of something familiar as something alien.","cn":"突然间领悟到熟悉的事物原来如此陌生"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"anxiety about the future, especially about dealing with something unpleasant or difficult 〔","cn":"对未来的〕忧虑﹐担心"},{"en":"the act of apprehending a criminal","cn":"逮捕﹐拘捕"},{"en":"understanding","cn":"了解"}]},"vocab":{"pos":"1 n 2 n 3 n","senses":[{"en":"Lucky you! Apprehension has three meanings: 1) the capture of a criminal; 2) the understanding of an idea; 3) a fear, doubt, or misgiving."}]},"collocations":{"phrases":["ADJ. considerable, great, growing | sudden","VERB + APPREHENSION be filled with, be full of, feel They were filled with apprehension as they approached the building. | express, show | o","APPREHENSION + VERB grow There were still areas of doubt and her apprehension grew.","PREP. with ~ School reports are always received with some apprehension. | ~ about/over her apprehension about being in hospital | ~ at She f","PHRASES a feeling/look of apprehension"]},"media":{"uk":"media/ldoce/hwd/bre/8/apprehension0205.mp3","us":"media/ldoce/hwd/ame/a/apprehension.mp3"},"examples":[{"en":"There is growing apprehension that fighting will begin again.","cn":"人们愈来愈担心会重开战火。"},{"en":"He watched the election results with some apprehension.","cn":"他不无忧虑地观察选举结果。"}],"oxford":{"phon":"ˌæprɪˈhenʃn","pos":"noun","senses":[{"en":"worry or fear that something unpleasant may happen","cn":"忧虑；担心；疑惧；恐惧","g":"[uncountable, countable]","ex":{"en":"There is growing apprehension that fighting will begin again.","cn":"人们愈来愈担心会重开战火。"}},{"en":"the act of capturing or arresting somebody, usually by the police","cn":"逮捕；拘押","g":"[uncountable]","lab":"formal","ex":{"en":"the apprehension of the terrorists in the early hours of this morning","cn":"今天凌晨逮捕了恐怖分子"}}]}},"apparatus":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"机构；组织","en":"The apparatus of an organization or system is its structure and method of operation.","ex":{"en":"For many years, the country had been buried under the apparatus of the regime.","cn":"多年来，这个国家一直处于该政权机构的高压统治下。"}},{"pos":"N-VAR 可变名词","cn":"器械;器具;仪器;设备","en":"Apparatus is the equipment, such as tools and machines, which is used to do a particular job or activity.","ex":{"en":"One of the boys had to be rescued by firemen wearing breathing apparatus.","cn":"其中一个男孩须由带着呼吸装置的消防员才能救出。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the machines, tools, or objects that you use for doing something","cn":""},{"en":"equipment and clothes for an activity that you do in your spare time","cn":""},{"en":"things for a particular purpose or activity, especially ones kept together in their own container","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Your apparatus is the collective equipment you use for specific purposes. For example, the apparatus used for scuba diving includes goggles, flippers, and a breathing tank, while a surgeon’s apparatus includes various scalpels and clamps. Different activities, different apparatus"}]},"collocations":{"phrases":["ADJ. breathing, chemical, electrical, experimental, laboratory, scientific | administrative, bureaucratic, legal, party, security, state the","QUANT. piece a very sophisticated piece of laboratory apparatus","PHRASES the apparatus of government/(the) state"]},"media":{"uk":"media/ldoce/hwd/bre/6/apparatus0205.mp3","us":"media/ldoce/hwd/ame/0/apparatus.mp3"},"examples":[{"en":"Firefighters needed breathing apparatus to enter the burning house.","cn":"消防队员需要呼吸器以便进入燃烧中的大楼。"},{"en":"the power of the state apparatus","cn":"国家机关的权力"}],"oxford":{"phon":"ˌæpəˈreɪtəs","pos":"noun","senses":[{"en":"the tools or other pieces of equipment that are needed for a particular activity or task","cn":"仪器；器械；装置","g":"[uncountable]","ex":{"en":"a piece of laboratory apparatus","cn":"一件实验室仪器"}},{"en":"the structure of a system or an organization, particularly that of a political party or a government","cn":"（尤指政党或政府的）机构，组织，机关","g":"[countable, usually singular]","ex":{"en":"the power of the state apparatus","cn":"国家机关的权力"}},{"en":"a system of organs in the body","cn":"器官","g":"[countable, usually singular]","lab":"specialist","ex":{"en":"the sensory apparatus","cn":"感觉器官"}}]}},"apathy":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"冷淡;漠然;漠不关心","en":"You can use apathy to talk about someone's state of mind if you are criticizing them because they do not seem to be interested in or enthusiastic about anything.","ex":{"en":"They told me about isolation and public apathy.","cn":"他们向我谈到了孤立无助和公众的冷漠。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling of not being interested in something, and not willing to make any effort to change or improve things","cn":"漠然﹐冷淡"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun apathy when someone isn't interested in the important things that are happening. You might feel apathy for the political process after watching candidates bicker tediously with one another."}]},"collocations":{"phrases":["ADJ. general, widespread | political, public","VERB + APATHY suffer from | fall into, sink into Once defeated, he sank into apathy. | lead to Such attitudes can only lead to apathy.","PREP. ~ among widespread apathy among students | ~ towards a general apathy towards politics"]},"media":{"uk":"media/ldoce/hwd/bre/2/apathy0205.mp3","us":"media/ldoce/hwd/ame/f/apathy.mp3"},"examples":[{"en":"There is widespread apathy among the electorate.","cn":"选民普遍态度冷淡。"},{"en":"The campaign failed because of public apathy.","cn":"由于公众反应冷淡﹐这次运动失败了。"}],"oxford":{"phon":"ˈæpəθi","pos":"noun","senses":[{"en":"the feeling of not being interested in or enthusiastic about something, or things in general","cn":"冷漠；淡漠","ex":{"en":"There is widespread apathy among the electorate.","cn":"选民普遍态度冷淡。"}}]}},"appetite":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"胃口;食欲","en":"Your appetite is your desire to eat.","ex":{"en":"He has a healthy appetite","cn":"他胃口很好。"}},{"pos":"N-COUNT 可数名词","cn":"强烈欲望;渴望","en":"Someone's appetite for something is their strong desire for it.","ex":{"en":"...his appetite for success.","cn":"他对成功的强烈渴望"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling you have when you have eaten very little food","cn":""},{"en":"the feeling of wanting to eat when you have not eaten for some time - use this especially when someone does not have their normal desire to eat, for example when they are ill","cn":""},{"en":"to start to feel hungry, especially because you have not eaten for some time","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"If you've filled your plate three times, you must have a strong appetite . I hope you still have room for dessert."}]},"collocations":{"phrases":["ADJ. big, enormous, gargantuan, good, healthy, hearty, huge, insatiable, large, ravenous special double-decker sandwiches for big appetites ","VERB + APPETITE have She had no appetite and began to lose weight. | lose | build up, develop, work up I went for a walk to work up an appet","APPETITE + VERB grow, increase | come back, return His appetite has returned to normal.","PHRASES a lack of appetite, a loss of appetite The symptoms include aching limbs and a loss of appetite. 2 strong desire for sth","ADJ. enormous, great, huge, insatiable, voracious an insatiable appetite for books | public The BBC recognizes the public appetite for serio","VERB + APPETITE have | lose | give sb | increase, revive, whet Reading the first story whetted my appetite for more. | dull | satisfy","APPETITE + VERB grow, increase","PREP. ~ for His appetite for power had grown."]},"media":{"uk":"media/ldoce/hwd/bre/6/appetite0205.mp3","us":"media/ldoce/hwd/ame/6/appetite.mp3"},"examples":[{"en":"Don't spoil your appetite by eating between meals.","cn":"不要在两餐之间吃东西，以免影响胃口。"},{"en":"The public have an insatiable appetite for scandal.","cn":"公众对丑事总是喜闻乐道。"}],"oxford":{"phon":"ˈæpɪtaɪt","pos":"noun","senses":[{"en":"physical desire for food","cn":"食欲；胃口","g":"[uncountable, countable, usually singular]","ex":{"en":"He suffered from headaches and loss of appetite.","cn":"他头痛，而且食欲不振。"}},{"en":"a strong desire for something","cn":"渴望；渴求","g":"[countable]","ex":{"en":"sexual appetites","cn":"性欲"}}]}},"apprehensive":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"担心的；忧虑的；恐惧的","en":"Someone who is apprehensive is afraid that something bad may happen.","ex":{"en":"People are still terribly apprehensive about the future.","cn":"人们对于将来仍然非常担心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not feeling happy or relaxed because you keep thinking about a problem or something bad that might happen","cn":""},{"en":"worried because you think something bad might happen or has happened. Anxious is more formal than worried , and is often used about a general feeling of worry, when you are not sure what has happened","cn":""},{"en":"worried or frightened about something you are going to do or experience, and unable to relax","cn":""}]},"vocab":{"pos":"1 adj 2 adj","senses":[{"en":"If you're apprehensive , you're anxious or fearful. If you just got run over by a crazy bicyclist, you might be a bit apprehensive crossing the street."}]},"collocations":{"phrases":["VERBS be, feel, look, seem, sound | become, get, grow | remain | make sb The long delay had made me quite apprehensive.","ADV. deeply, extremely, very | a bit, a little, quite, rather, slightly","PREP. about She was deeply apprehensive about her future. | of He was rather apprehensive of failure."]},"media":{"uk":"media/ldoce/hwd/bre/e/apprehensive0205.mp3","us":"media/ldoce/hwd/ame/7/apprehensive.mp3"},"examples":[{"en":"I was a little apprehensive about the effects of what I had said.","cn":"我有点担忧我说的话所带来的影响。"},{"en":"She was deeply apprehensive that something might go wrong.","cn":"她很担心可能要出什么差错。"}],"oxford":{"phon":"ˌæprɪˈhensɪv","pos":"adjective","senses":[{"en":"worried or frightened that something unpleasant may happen","cn":"忧虑的；担心的；疑惧的；恐惧的","ex":{"en":"an apprehensive face/glance/look","cn":"忧虑的面容／一瞥／目光"}}]}},"approximation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"接近；近似","en":"An approximation is a fact, object, or description which is similar to something else, but which is not exactly the same.","ex":{"en":"That is a fair approximation of the way in which the next boss is being chosen.","cn":"那和下一任老板的选任方式相当类似。"}},{"pos":"N-COUNT 可数名词","cn":"近似值；粗略估计","en":"An approximation is a number, calculation, or position that is close to a correct number, time, or position, but is not exact.","ex":{"en":"Clearly that's an approximation, but my guess is there'll be a reasonable balance.","cn":"很明显那是个粗略的估计，但我猜会有一笔不少的余额。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"approximately correct, and therefore not to be used for detailed or important work","cn":""},{"en":"a number or amount that is approximately correct - used especially in business","cn":""},{"en":"a number or amount that is approximately correct","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"An approximation is a rough estimate or guess at something. When you write a budget for the month, you're making an approximation of how much you're going to spend. You can't be certain of the exact amount."}]},"collocations":{"phrases":["ADJ. close, good, nearest, reasonable This is the nearest approximation of cost that they can give us. | crude, rough This is only a crude a","VERB + APPROXIMATION make We do not have the true figures so we will have to make some approximations. | give (sb), provide (sb with)"]},"media":{"uk":"media/ldoce/hwd/bre/0/ld41approximation.mp3","us":"media/ldoce/hwd/ame/2/approximation.mp3"},"examples":[{"en":"Our results should be a good approximation of the true state of affairs.","cn":"我们的结果应该和实际情况相当接近。"},{"en":"That's just an approximation, you understand.","cn":"你知道那仅仅是近似值。"}],"oxford":{"phon":"əˌprɒksɪˈmeɪʃn","pos":"noun","senses":[{"en":"an estimate of a number or an amount that is almost correct, but not exact","cn":"近似值；粗略估算","ex":{"en":"That's just an approximation, you understand.","cn":"你知道那仅仅是近似值。"}},{"en":"a thing that is similar to something else, but is not exactly the same","cn":"类似事物","ex":{"en":"Our results should be a good approximation of the true state of affairs.","cn":"我们的结果应该和实际情况相当接近。"}}]}}});
